
// ── App version & rollback archive ───────────────────────────────────────────
// APP_VERSION is bumped with each release. On startup the app archives its own
// source into IndexedDB (first run of each version), keeping the last 8, so any
// previous version can be re-downloaded as a working .html file ("versions"
// link in Setup). Captured here, before scripts modify the page.
const APP_VERSION='2026.08.19-825-open';
// v824 — stop-distance text for the holdings chip. The old template hardcoded
// the minus sign, so a stop AT the buy price printed '(-0.0%)' (Tony's PNN
// screenshot, 19 Aug) and a break-even stop lifted ABOVE buy would read as
// negative. Say what it is: at buy price, X% below, or X% above (profit locked).
function _stopPctTxt(buy,stop){ var b=+buy, st=+stop; if(!(b>0&&st>0))return '';
  var v=((b-st)/b)*100;
  if(v<0.05&&v>-0.05)return '(at buy price)';
  return v>0?('(-'+v.toFixed(1)+'% below buy)'):('(+'+Math.abs(v).toFixed(1)+'% above buy \u2014 profit locked)'); }
// ── Make the app installable (PWA) without needing a separate manifest file ──
// We build the manifest in-memory and attach it as a Blob URL, so the whole app
// stays a single HTML file you can upload as-is. Phones/desktops then offer
// "Install" / "Add to Home screen" with the proper name and chart-bars icon.
(function(){try{
  const icon="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 512 512'%3E%3Crect width='512' height='512' rx='96' fill='%230d1b33'/%3E%3Crect x='104' y='300' width='60' height='128' rx='10' fill='%23FFD200'/%3E%3Crect x='196' y='232' width='60' height='196' rx='10' fill='%23FFD200'/%3E%3Crect x='288' y='168' width='60' height='260' rx='10' fill='%23FFD200'/%3E%3Crect x='380' y='96' width='60' height='332' rx='10' fill='%23FFD200'/%3E%3C/svg%3E";
  const manifest={
    name:"Insight Trading — Share Screener",
    short_name:"Insight Trading",
    description:"Multi-exchange end-of-day share screener.",
    start_url:".",
    scope:".",
    display:"standalone",
    orientation:"any",
    background_color:"#05152e",
    theme_color:"#0d1b33",
    icons:[
      {src:icon,sizes:"512x512",type:"image/svg+xml",purpose:"any maskable"},
      {src:icon,sizes:"192x192",type:"image/svg+xml",purpose:"any maskable"}
    ]
  };
  const blob=new Blob([JSON.stringify(manifest)],{type:'application/manifest+json'});
  const url=URL.createObjectURL(blob);
  const link=document.createElement('link');
  link.rel='manifest'; link.href=url;
  document.head.appendChild(link);
}catch(e){}})();
const COPYRIGHT='© 2026 Insight Trading™. All rights reserved. · ABN 49 691 811 293';
let APP_SOURCE_SNAPSHOT='';
async function _appSourceSnapshot(){ /* v814: the app's code now lives in app.js (external scripts get the browser's compile cache \u2014 the load-speed fix), so a TRUE single-file archive must re-inline it. If the fetch fails (offline very first run of a version) we return '' and archiving simply retries on a later run \u2014 the store only writes when this version is absent. */
  if(APP_SOURCE_SNAPSHOT)return APP_SOURCE_SNAPSHOT;
  try{
    var shell='<!DOCTYPE html>\n'+document.documentElement.outerHTML;
    var r=await fetch('app.js?v='+APP_VERSION,{cache:'force-cache'});
    if(!r||!r.ok)return '';
    var js=await r.text();
    if(!js||js.length<10000)return '';
    var re=/<script src="app\.js[^"]*"><\/script>/;
    if(!re.test(shell))return '';
    APP_SOURCE_SNAPSHOT=shell.replace(re,function(){return '<script>'+js+'</'+'script>';});
    return APP_SOURCE_SNAPSHOT;
  }catch(e){ return ''; }
}
function _verDB(){return new Promise((res,rej)=>{
  const rq=indexedDB.open('pnmaVersions',1);
  rq.onupgradeneeded=()=>{if(!rq.result.objectStoreNames.contains('versions'))rq.result.createObjectStore('versions',{keyPath:'v'});};
  rq.onsuccess=()=>res(rq.result);rq.onerror=()=>rej(rq.error);
});}
async function saveVersionSnapshot(){
  try{
    const SNAP=await _appSourceSnapshot();
    if(!SNAP||SNAP.length<10000)return; // sanity: don't archive a broken capture (also: offline first run \u2014 retries next run)
    const db=await _verDB();
    await new Promise((res)=>{ // only archive the first time this version runs
      const tx=db.transaction('versions','readwrite');const st=tx.objectStore('versions');
      const g=st.get(APP_VERSION);
      g.onsuccess=()=>{
        if(!g.result)st.put({v:APP_VERSION,date:new Date().toISOString().slice(0,16).replace('T',' '),size:SNAP.length,html:SNAP});
      };
      tx.oncomplete=res;tx.onerror=res;
    });
    // prune: keep newest 8 by version string (date-based, so sortable)
    await new Promise((res)=>{
      const tx=db.transaction('versions','readwrite');const st=tx.objectStore('versions');
      const all=st.getAllKeys();
      all.onsuccess=()=>{
        const keys=(all.result||[]).sort();
        keys.slice(0,Math.max(0,keys.length-8)).forEach(k=>st.delete(k));
      };
      tx.oncomplete=res;tx.onerror=res;
    });
  }catch(e){}
}
async function showVersionPanel(){
  let rows=[];
  try{
    const db=await _verDB();
    rows=await new Promise((res)=>{const g=db.transaction('versions').objectStore('versions').getAll();g.onsuccess=()=>res(g.result||[]);g.onerror=()=>res([]);});
  }catch(e){}
  rows.sort((a,b)=>a.v<b.v?1:-1);
  const list=rows.length?rows.map(r=>`
    <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 9px;border:1px solid var(--border);border-radius:7px;margin-bottom:6px;${r.v===APP_VERSION?'background:rgba(255,210,0,.07);border-color:var(--gold);':''}">
      <div><strong style="color:${r.v===APP_VERSION?'var(--gold)':'var(--text)'};font-size:11px;">v${r.v}</strong>${r.v===APP_VERSION?' <span style="font-size:9px;color:var(--gold)">current</span>':''}<br><span style="font-size:9px;color:var(--muted)">archived ${r.date} · ${(r.size/1024).toFixed(0)} KB</span></div>
      <button onclick="downloadVersion('${r.v}')" style="padding:5px 12px;border-radius:5px;border:1px solid var(--blue);background:rgba(56,139,253,.12);color:var(--blue);font-weight:600;font-size:10px;font-family:var(--sans);cursor:pointer;">⬇ Download</button>
    </div>`).join('')
    :'<div style="font-size:10px;color:var(--muted);padding:10px;text-align:center;">No versions archived yet — each new version archives itself the first time it runs.</div>';
  showModal(`
    <div style="font-weight:700;font-size:15px;color:var(--text);">🗂 Version history & rollback</div>
    <div style="font-size:10px;color:var(--muted);margin:6px 0 10px;">The app archives its own code the first time each version runs (last 8 kept). To roll back: download an older version, open that file, and use it instead — your watchlists, portfolio, licence and cached data are shared between versions on this computer, so nothing is lost.</div>
    ${list}
    <div style="font-size:9px;color:var(--orange);margin-top:6px;">Tip: also keep your own copies of the file — an external backup beats any built-in one.</div>
  `);
}
async function downloadVersion(v){
  try{
    const db=await _verDB();
    const r=await new Promise((res)=>{const g=db.transaction('versions').objectStore('versions').get(v);g.onsuccess=()=>res(g.result);g.onerror=()=>res(null);});
    if(!r||!r.html){alert('Version not found.');return;}
    const blob=new Blob([r.html],{type:'text/html;charset=utf-8;'});
    const a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download=`insight-trading_v${v}.html`;
    document.body.appendChild(a);a.click();document.body.removeChild(a);
  }catch(e){alert('Could not retrieve that version.');}
}

