let LANG='en';
function t(key){const d=I18N[LANG]||I18N.en;return (d&&d[key]!=null)?d[key]:(I18N.en[key]!=null?I18N.en[key]:key);}
function applyLang(){
  document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t(el.getAttribute('data-i18n'));});
  document.querySelectorAll('[data-i18n-ph]').forEach(el=>{el.setAttribute('placeholder',t(el.getAttribute('data-i18n-ph')));});
  document.querySelectorAll('[data-i18n-title]').forEach(el=>{el.setAttribute('title',t(el.getAttribute('data-i18n-title')));});
  // Right-to-left for Arabic
  document.documentElement.dir = (LANG==='ar') ? 'rtl' : 'ltr';
}
function setLang(code){
  LANG=code;
  try{localStorage.setItem('asxScreener.lang',code);}catch(e){}
  const sel=document.getElementById('langSel');if(sel)sel.value=code;
  applyLang();
}
function initLang(){
  let saved='en';
  try{saved=localStorage.getItem('asxScreener.lang')||'en';}catch(e){}
  setLang(saved);
}

let allData=[], filtered=[], currentExch='ASX';
// v483 — demo data removed at Tony's request ("we can remove demo data as we
// dont require"). It existed so a new user could press buttons before they had
// a data key; it also carried the _history that made exiting training mode wipe
// the real market. 411 KB smaller, and one whole class of bug gone.












































































let lastScanLabel='';
let sortKey='volPct', sortDir=-1;
// Dual-slider scale stops (index 0–8). Index 8 = open-ended top (Any/∞).
const RANGE_STOPS=[0,5,10,20,30,40,50,100,Infinity];
const F={
  dir:'all',days:'0',daysMin:0,news:'any',cap:'any',rsi:'any',sm:'any',annq:'any',
  pctLo:0, pctHi:Infinity,   // % change min/max
  volLo:0, volHi:Infinity,   // volume surge min/max
  pMin:0,pMax:500,vMin:0,vMax:50,
  vMinAbs:0, vMaxAbs:Infinity, // exact share counts (source of truth)
  buyDays:0, // min consecutive buying-pressure days (0=off, 1–5)
  volStreakDays:0, // min consecutive days volume above average (0=off, 1–5)
  minScore:0, // min watch score /10 (0=off) — same scale as Top 20 & Score column
  accumMin:0, // min qualifying days (price up + vol 50%+) in last 10 (0=off)
};
// v295: the 💧 Liquidity floor is remembered across sessions, and BRAND-NEW users
// start at ≥$50k/day (thinly-traded shares are hard to exit at a fair price).
// One tap back to "Any" — and that choice sticks. Existing users keep their setting.
const LIQ_PREF_KEY='asxScreener.liqPref.v1';
function _liqSave(){ try{ localStorage.setItem(LIQ_PREF_KEY,F.cap); }catch(e){} }
(function _liqInit(){ try{
  const v=localStorage.getItem(LIQ_PREF_KEY);
  if(v==='any'||v==='l50'||v==='l250'||v==='l1m'){ F.cap=v; }
  else { F.cap='l50'; _liqSave(); }
  document.addEventListener('DOMContentLoaded',function(){ try{ if(typeof rst1==='function')rst1('gCap',F.cap,'cap'); }catch(e){} });
}catch(e){} })();
// ── Multiple persistent watchlists ──────────────────────────
// Stored as { listName: { TICKER: {savedStockSnapshot} } } in localStorage so
// they survive browser closes AND show regardless of current filters.
const WL_KEY='asxScreener.watchlists.v1';
let watchlists={};       // all named lists
let activeWatch='My Watchlist'; // currently selected list name
let watchViewOn=false;   // showing the watchlist view (independent of filters)?

// ── v259 security: sanitise text that arrives from OUTSIDE the app ──────────
// Applied at the data boundary (API rows, imports, stored lists, prompts) so
// every downstream render — table, panels, print windows — is safe without
// touching each of the ~170 render sites individually.
function _sanText(v,max){
  v=String(v==null?'':v).replace(/[<>"'`\\]/g,'').replace(/\s+/g,' ').trim();
  if(max&&v.length>max)v=v.slice(0,max);
  return v;
}
function _sanTicker(v){ return String(v==null?'':v).toUpperCase().replace(/[^A-Z0-9._:\-]/g,'').slice(0,16); }
// ═══ v454 — supplier name corrections ═══════════════════════════════════════
// The data supplier's reference file can lag corporate renames / ticker
// reassignments (found in the wild: ASX GLS still labelled with a previous
// holder's name while the code now belongs to L1 Global Long Short Fund).
// Prices key off the TICKER, so signals and orders were always right — but
// the label feeds the eye and the news matcher, so it must be right too.
// Add corrections as 'EXCH|TICKER': 'Correct Name'.
var _NAME_FIX={
  'ASX|GLS':'L1 Global Long Short Fund Ltd'
};
function _fixShareName(ticker,exch,name){
  try{
    var k=String(exch||'ASX').toUpperCase()+'|'+String(ticker||'').toUpperCase();
    return _NAME_FIX[k]||name;
  }catch(e){ return name; }
}
function _sanShare(s){
  if(!s||typeof s!=='object')return s;
  try{
    if('ticker' in s)s.ticker=_sanTicker(s.ticker);
    if('name' in s)s.name=_sanText(s.name,120);
    if('name' in s&&s.ticker)s.name=_fixShareName(s.ticker,s.exchange,s.name);   // v454: stale stored labels self-heal
    if('exchange' in s)s.exchange=_sanText(s.exchange,12);
    if('currency' in s)s.currency=_sanText(s.currency,8);
    if('type' in s)s.type=_sanText(s.type,20);
    if('annTitle' in s&&s.annTitle)s.annTitle=_sanText(s.annTitle,160);
    if('annHeadline' in s&&s.annHeadline)s.annHeadline=_sanText(s.annHeadline,160); // v285
  }catch(e){}
  return s;
}
function _sanPaper(p){
  try{ (p.holdings||[]).concat(p.history||[]).forEach(h=>{ if(h&&typeof h==='object'){ _sanShare(h); if(h.note!=null)h.note=_sanText(h.note,140)||null; } }); }catch(e){}
  // v372 SECURITY: orders + dividends were NOT cleaned — a hostile order in a SHARED/PASTED backup
  // could inject markup into the ⏳ Pending panel (stored XSS that could read the API key on import).
  // Sanitise them at the boundary too, the same way holdings/history are, so every render is safe.
  try{ (p.orders||[]).forEach(o=>{ if(o&&typeof o==='object'){ _sanShare(o); if(o.note!=null)o.note=_sanText(o.note,140)||null; if(o.expiry!=null)o.expiry=_sanText(o.expiry,24); if(o.id!=null)o.id=_sanText(o.id,40); } }); }catch(e){}
  try{ (p.dividends||[]).forEach(d=>{ if(d&&typeof d==='object'){ _sanShare(d); if(d.note!=null)d.note=_sanText(d.note,140)||null; } }); }catch(e){}
  return p;
}
function _sanResearch(){
  try{
    const cl={};
    Object.keys(researchList||{}).forEach(k=>{
      const it=researchList[k]; if(!it||typeof it!=='object')return;
      _sanShare(it); if(it.snap&&typeof it.snap==='object')_sanShare(it.snap);
      if(it.note!=null)it.note=_sanText(it.note,200);
      const ck=_sanTicker(k); if(ck)cl[ck]=it;
    });
    researchList=cl;
  }catch(e){}
}
// Escape for the few places that draw third-party text (live headlines).
function _escHtml(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
// Links from third-party feeds may only be web links — never javascript: etc.
function _safeUrl(u){u=String(u||'').trim();return /^https?:\/\//i.test(u)?u.replace(/"/g,'%22'):'#';}
// ── v373b: DATA SERVER (Phase 1) ────────────────────────────────────────────
// Route market data through our own Cloudflare Worker: fast, edge-cached, and the
// EODData API key is held SERVER-SIDE (never shipped to the browser, never handed
// to public relays). If the Worker is ever unreachable the app falls back to the
// existing direct + free-relay routes, so an outage can't dark the app.
// Override or disable at runtime via localStorage 'asxScreener.dataProxy.v1'
// (set it to '' to turn the server off and use the old relays).
let DATA_PROXY='https://insight-data.tonycotton13.workers.dev';
