// that doubled as a complete takeover: one hostile extension, or one successful
// injection, could repoint every request at an attacker's server permanently —
// and the fetch wrapper below would then hand them the access key. Nothing in
// the product needed it.
// ═════ v689 — guided broker connect (SnapTrade via the worker + bridge) ═════
async function cleanOldExchanges(){ // v693 — 7,734 saved shares when the ASX is ~4,400: the rest is retired-exchange history slowing every load
  var msg=document.getElementById('cleanExMsg');
  var say=function(t,c){ if(msg){msg.textContent=t; msg.style.color=c||'var(--muted)';} };
  try{
    var keep=(document.getElementById('exchSel')||{}).value||'ASX';
    var exs=await offlineExchangeList();
    var others=(exs||[]).filter(function(e){return e.exch!==keep;});
    if(!others.length){ say('Nothing to clean — only '+keep+' data is saved. ✓','var(--green)'); return; }
    var total=others.reduce(function(a,e){return a+(e.count||0);},0);
    var names=others.map(function(e){return e.exch+' ('+(e.count||0).toLocaleString()+')';}).join(', ');
    if(!confirm('Delete saved history for '+names+'?\n\nYour '+keep+' data, portfolio and lists are untouched. This cannot be undone (a re-download would restore it).')) return;
    say('Cleaning\u2026');
    var db=await cacheOpen(); if(!db){ say('Could not open the data store.','#ff8b8b'); return; }
    var freed=0;
    for(var i=0;i<others.length;i++){
      var ex=others[i].exch;
      freed+=await new Promise(function(res){
        try{
          var tx=db.transaction(HIST_STORE,'readwrite'), st=tx.objectStore(HIST_STORE);
          var rng=IDBKeyRange.bound(ex+':', ex+':\uffff');
          var nDel=0, cur=st.openCursor(rng);
          cur.onsuccess=function(e2){ var c=e2.target.result; if(c){ c.delete(); nDel++; c.continue(); } };
          tx.oncomplete=function(){ res(nDel); }; tx.onerror=function(){ res(nDel); };
        }catch(_){ res(0); }
      });
    }
    say('\u2713 Removed '+freed.toLocaleString()+' saved shares from '+others.map(function(e){return e.exch;}).join(', ')+'. Loads will be lighter from the next open.','var(--green)');
    try{ if(typeof _refreshSimpleLoad==='function')_refreshSimpleLoad(); }catch(_){}
  }catch(e){ say('Cleanup failed: '+(e&&e.message||e),'#ff8b8b'); }
}
function _connStop(){ try{ if(window._connT){clearInterval(window._connT); window._connT=null;} }catch(_){} }
function connectBroker(){
  _connStop();
  showModal('<div id="connBody" style="min-height:90px;font-size:14px;line-height:1.55;">Checking your connection\u2026</div>', '🔗 Connect your broker') /* v715: args were reversed - the wizard body was rendering inside the label chip */;
  fetch(DATA_PROXY+'/connect/start',{method:'POST'}).catch(function(){});
  _connTick(); window._connT=setInterval(_connTick, 4000);
}
async function _connTick(){
  var el=document.getElementById('connBody');
  if(!el){ _connStop(); return; }
  var j=null;
  try{ var r=await fetch(DATA_PROXY+'/connect/status'); j=await r.json(); }catch(e){ el.innerHTML='Could not reach the server \u2014 check your internet, this screen retries by itself.'; return; }
  if(!j || j.ok!==true){ el.innerHTML='Could not read your connection status \u2014 retrying\u2026'; return; }
  if(!j.status || j.status==='requested'){
    el.innerHTML='<b>Preparing your private connection link\u2026</b><br><span style="color:var(--muted);font-size:12px;">Usually under a minute. This screen updates itself.</span>';
    return;
  }
  if(j.status==='portal_ready'){
    el.innerHTML='<a href="'+j.portal_url+'" target="_blank" rel="noopener" style="display:inline-block;padding:10px 16px;border-radius:9px;background:var(--gold);color:#1c2333;font-weight:700;text-decoration:none;">Open the secure Stake connection \u2192</a>'
      +'<div style="margin-top:10px;font-size:13px;">1. Choose <b>Stake AUS</b> (not Stake US).<br>2. Log in on SnapTrade\u2019s page \u2014 your password never touches Insight.<br>3. Approve, then come back \u2014 this screen updates itself.</div>';
    return;
  }
  if(j.status==='connected'){
    var accs=Array.isArray(j.accounts)?j.accounts:[];
    if(j.account_id){
      _connStop();
      var pick=null; for(var i=0;i<accs.length;i++){ if(accs[i]&&accs[i].id===j.account_id) pick=accs[i]; }
      el.innerHTML='\u2705 <b>Connected.</b> Orders will queue against <b>'+((pick&&(pick.name||pick.number))||j.account_id)+'</b> \u2014 approve-each, nothing places on its own.';
      return;
    }
    if(!accs.length){ el.innerHTML='\u2705 Connected \u2014 waiting for your account list\u2026'; return; }
    var h='<b>Connected \u2014 pick the account to use:</b><div style="margin:8px 0;">';
    for(var i2=0;i2<accs.length;i2++){ var a=accs[i2]||{};
      h+='<label style="display:block;margin:4px 0;"><input type="radio" name="connAcct" value="'+(a.id||'')+'"> '+(a.name||'Account')+' '+(a.number?('\u00b7 '+a.number):'')+'</label>';
    }
    h+='</div><button type="button" onclick="_connChoose()" style="padding:8px 14px;border-radius:8px;border:1px solid var(--line);background:var(--bg3);color:var(--text);cursor:pointer;font-weight:600;">Use this account</button>';
    el.innerHTML=h;
    return;
  }
  if(j.status==='failed'){
    _connStop();
    el.innerHTML='\u26a0 The connection attempt failed'+(j.note?(': '+j.note):'.')+'<br><button type="button" onclick="_connRetry()" style="margin-top:8px;padding:8px 14px;border-radius:8px;border:1px solid var(--line);background:var(--bg3);color:var(--text);cursor:pointer;font-weight:600;">Try again</button>';
  }
}
async function _connChoose(){
  var sel=document.querySelector('input[name=connAcct]:checked');
  if(!sel||!sel.value) return;
  try{ await fetch(DATA_PROXY+'/connect/choose',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({account_id:sel.value})}); }catch(e){}
  _connTick();
}
function _connRetry(){
  fetch(DATA_PROXY+'/connect/start?force=1',{method:'POST'}).catch(function(){});
  var el=document.getElementById('connBody'); if(el)el.innerHTML='Starting again\u2026';
  if(!window._connT) window._connT=setInterval(_connTick,4000);
}
function _serverData(){ return (typeof DATA_PROXY==='string' && !!DATA_PROXY); } // v382: the Worker provides the data, so no user API key is needed
// ═══ v380 — ACCESS GATE (client side) ══════════════════════════════════════
// A shared "tester password" that the Worker enforces server-side (it refuses to
