// The research list view — a worklist you clear, not a collection you keep.
// v646 — TODAY'S PICKS, in the app rather than behind the admin password.
// The daily selection has run on the server for weeks, but the only way to see
// it was an admin page with a separate password — so a report nobody could
// reach was a report nobody read. This reads the same rows over the app's own
// access gate.
//
// READ ONLY, deliberately. Clearing, re-running and queueing orders all change
// state and stay on the admin page. This shows what the rules chose; buying is
// still done through the normal buy flow, so every existing cap, the stop rule
// and the practice-money boundary continue to apply exactly as before.
// v647 - opening a pick. showShareDetail is the main share console: chart,
// history, evidence, diary and the buy controls. It needs the share to be in
// the loaded market though, and a pick can name one this device has not
// downloaded - the raw function alerts "Share not found." and leaves you
// nowhere. This says what actually happened and offers the report card, which
// fetches its own data and works either way.
// v651 - buying a pick. This opens the NORMAL buy dialog and pre-fills it from
// the pick: limit order at the buy-under price, with the take-profit and stop
// the rules chose. Everything after that is the app's existing flow, on purpose
// - the caps, the checklist, the stale-data warning and the confirm step all
// still apply, and nothing is placed until you press the confirm yourself.
// v656 - the price-met badge on each pending order. Reads the saved daily
// history and reports, from COMPLETED sessions only, whether the limit has been
// reached since the order was placed. Deliberately skips the placement day: this
// is an end-of-day app, so that day's low happened before the order existed and
// filling on it would be hindsight - the same rule the fill engine uses.
/* v665 - WHERE THE EXIT ACTUALLY SITS, for each holding.
   With a 20% trail and no take-profit, the trailing stop IS the position: it
   decides everything, moves every day, and until now it was invisible until it
   fired. You could not tell a holding 2% from being sold from one with 18% of
   room left.
   This RE-USES the same arithmetic checkAutoSellTargets uses to decide a real
   exit - manual stop wins outright, otherwise the highest of stop, break-even,
   trail and ladder lock. Re-deriving it separately would let the number on
   screen drift away from the number that acts, which is the worst possible
   failure for this particular display. */
window._pfEffectiveStop = function(h, R){
  try{
    const r = R || _rules();
    let s = (h.stop > 0 ? h.stop : 0);
    if (h.stopSrc === 'manual') return { stop: s, src: 'your own stop' };
    let src = s > 0 ? 'stop' : null;
    if (r.bePct > 0 && h.beArmed === true && h.buyPrice > 0 && h.buyPrice > s) { s = h.buyPrice; src = 'break-even'; }
    if (r.trailPct > 0 && (h.peakClose || 0) > 0) {
      const t = +(((h.peakClose) * (1 - r.trailPct / 100))).toFixed(4);
      if (t > s) { s = t; src = 'trail'; }
    }
    if ((+h.ladderLock || 0) > 0 && h.buyPrice > 0) {
      const l = +((h.buyPrice * (1 + h.ladderLock / 100))).toFixed(4);
      if (l > s) { s = l; src = 'ladder lock'; }
    }
    return { stop: s, src: src };
  }catch(e){ return { stop: 0, src: null }; }
};
window._pfRoomPass = function(){
  let hold = [];
  try{ hold = (_paper(window._pfCtx).holdings || []); }catch(e){ return; }
  let R = null; try{ R = _rules(); }catch(e){ return; }
  for (const h of hold) {
    const el = document.getElementById('room_' + h.id);
    if (!el) continue;
    const px = +h.lastPrice || +h.buyPrice || 0;
    const E = _pfEffectiveStop(h, R);
    if (!(px > 0) || !(E.stop > 0)) {
      el.innerHTML = '<span style="color:var(--muted)">no stop on this holding \u2014 nothing will sell it automatically</span>';
      continue;
    }
    const roomPct = ((px - E.stop) / px) * 100;
    const roomDollars = (px - E.stop) * (+h.qty || 0);
    /* coloured by how TIGHT it is, not by profit - this is about how close the
       exit is, and a position deep in profit can still be one bad day from it */
    const col = roomPct <= 3 ? '#ff9caa' : (roomPct <= 8 ? 'var(--gold)' : 'var(--green)');
    let peakBit = '';
    if (E.src === 'trail' && (h.peakClose || 0) > 0) {
      const offPeak = ((h.peakClose - px) / h.peakClose) * 100;
      peakBit = ' \u00b7 best close ' + fmtP(h.peakClose, h.currency)
        + (offPeak > 0.05 ? (', now ' + offPeak.toFixed(1) + '% under it') : ', sitting at its high');
    }
    el.innerHTML = '<span style="color:' + col + ';font-weight:700;">' + roomPct.toFixed(1) + '% of room</span>'
      + '<span style="color:var(--muted)"> before it sells at ' + fmtP(E.stop, h.currency)
      + (E.src ? (' (' + E.src + ')') : '')
      + ' \u2014 ' + fmtP(roomDollars, h.currency) + ' of this position' + peakBit + '</span>';
  }
};
window._pfPriceMetPass = async function(){
  let orders=[];
  try{ orders=(_paper(window._pfCtx).orders||[]); }catch(e){ return; }
  for(const o of orders){
    const el=document.getElementById('met_'+o.id);
    if(!el) continue;
    if(o.side==='sell'){ el.innerHTML=''; continue; }
    try{
      const c=await histGet(o.exchange,o.ticker);
      const rows=(c&&Array.isArray(c.rows))?c.rows:null;
      if(!rows||!rows.length){ el.innerHTML='<span style="color:var(--muted)">no saved history for this share yet</span>'; continue; }
      const dOf=r=>String((r&&(r.dateStamp||r.date||r.Date))||'').slice(0,10);
      const num=(r,k)=>{for(const x of k){const v=parseFloat(r&&r[x]);if(isFinite(v))return v;}return NaN;};
      const lim=+o.limit||0;
      const days=rows.map(r=>({d:dOf(r),o:num(r,['open','Open']),lo:num(r,['low','Low']),c:num(r,['close','Close'])}))
        .filter(x=>x.d && !(x.d<o.placedDate || (x.d===o.placedDate && !o.preOpen)))
        .sort((a,b)=>a.d<b.d?-1:1);
      if(!days.length){ el.innerHTML='<span style="color:var(--muted)">no completed session since you placed it</span>'; continue; }
      let metOn=null, best=Infinity;
      for(const x of days){
        const cand=[x.o,x.lo,x.c].filter(v=>isFinite(v)&&v>0);
        if(!cand.length) continue;
        const m=Math.min.apply(null,cand);
        if(m<best) best=m;
        if(!metOn && lim>0 && m<=lim) metOn=x.d;
      }
      if(metOn){
        el.innerHTML='<span style="color:var(--green)">\u2713 your price was reached on '+metOn+'</span>'
          +'<span style="color:var(--muted)"> \u2014 if it is still pending, load fresh prices and it should fill</span>';
      } else if(best===Infinity){
        el.innerHTML='<span style="color:var(--muted)">those sessions carry no usable prices</span>';
      } else {
        const away=lim>0?(((best/lim)-1)*100):0;
        el.innerHTML='<span style="color:var(--muted)">price not reached \u2014 cheapest since you ordered was '
          +fmtP(best,o.currency)+', '+away.toFixed(1)+'% above your limit</span>';
      }
    }catch(e){ try{ el.innerHTML=''; }catch(_){ } }
  }
};
window._picksBuy = function(ticker, limitPx, tgtPx, stopPx, trailPct){
  const have = (typeof allData!=='undefined') && allData.some(x=>x.ticker===ticker);
  if(!have){
    if(typeof showModal==='function'){
      window._modalLabel='\ud83d\uded2 '+ticker;
      showModal('<div style="padding:22px 12px;text-align:center;font-size:13px;color:var(--muted);line-height:1.6;">'
        +'<b style="color:var(--text);font-size:15px;">'+ticker+' is not in the loaded market yet</b><br>'
        +'A practice buy needs this share\u2019s price on this device. Load the market first, then buy from here or from the share itself.</div>');
    }
    return;
  }
  try{ paperBuy(ticker); }catch(e){ return; }
  // fill in AFTER the dialog exists. Guarded individually: a missing field must
  // never stop the rest, and must never leave a half-filled order looking whole.
  setTimeout(function(){
    try{
      if(limitPx>0 && typeof _setBuyType==='function'){
        _setBuyType('limit');
        const L=document.getElementById('paperLimit');
        if(L){ L.value=limitPx; try{ L.dispatchEvent(new Event('input',{bubbles:true})); }catch(e){} }
      }
      if(tgtPx>0){ const T=document.getElementById('paperTgt');
        if(T){ T.value=tgtPx; try{ T.dispatchEvent(new Event('input',{bubbles:true})); }catch(e){} } }
      if(stopPx>0){ const S=document.getElementById('paperStop');
        if(S){ S.value=stopPx; try{ S.dispatchEvent(new Event('input',{bubbles:true})); }catch(e){} } }
      // v746 — a trail-lane pick has NO take-profit by design. Mirror it exactly:
      // set the pick's own trailing %, and blank the 🎯 fields that paperBuy
      // pre-filled from saved rules, so the form shows the pick, not a hybrid.
      if(trailPct>0){ const W=document.getElementById('paperTrailPct');
        if(W){ W.value=trailPct; try{ W.dispatchEvent(new Event('input',{bubbles:true})); }catch(e){} }
        if(!(tgtPx>0)){
          for(const id of ['paperTgt','paperTgtPct']){ const F=document.getElementById(id);
            if(F){ F.value=''; try{ F.dispatchEvent(new Event('input',{bubbles:true})); }catch(e){} } }
        }
      }
      const note=document.getElementById('paperBuyPrev');
      if(note) note.innerHTML='<span style="color:var(--gold)">Filled in from today\u2019s pick. Check the amount, then confirm - nothing is placed until you do.</span>';
    }catch(e){}
  }, 60);
};
