  var C={bg2:'var(--bg2)',bd:'var(--border)',bd2:'var(--border2)',tx:'var(--text)',dim:'var(--dim)',grn:'var(--green,#1f9d57)',red:'var(--red,#d64550)',acc:'var(--purple,#6a4bd0)'};
  ov.innerHTML=''
   +'<div style="background:'+C.bg2+';border:1px solid '+C.bd+';border-radius:16px;max-width:440px;width:100%;padding:18px 16px 20px;font-family:var(--sans);box-shadow:0 10px 40px rgba(0,0,0,.4);margin:auto;">'
   +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;">'
   +'<div style="font-size:17px;font-weight:700;color:'+C.tx+';">🧮 Trade Calculator</div>'
   +'<button onclick="document.getElementById(\'calcToolsOv\').remove()" style="border:none;background:none;font-size:20px;color:'+C.dim+';cursor:pointer;line-height:1;padding:2px 6px;">✕</button>'
   +'</div>'
   +'<div style="font-size:12.5px;color:'+C.dim+';margin-bottom:14px;">Your numbers, your costs, your profit. Nothing is assumed.</div>'
   +'<div style="display:grid;gap:10px;">'
   +_calcField('Entry price','$','_cEntry','1.00')
   +_calcField('How much are you putting in?','$','_cParcel','2000')
   +'<div><div style="font-size:12.5px;font-weight:600;color:'+C.tx+';margin-bottom:5px;">Exit</div>'
   +'<div style="display:flex;gap:6px;margin-bottom:6px;"><button id="_cMp" onclick="_calcMode(\'pct\')" style="flex:1;border:1.5px solid '+C.acc+';background:var(--purplebg,#efeafc);color:'+C.acc+';border-radius:9px;padding:8px;font-size:13px;font-weight:600;cursor:pointer;font-family:var(--sans);">% gain</button>'
   +'<button id="_cMs" onclick="_calcMode(\'price\')" style="flex:1;border:1.5px solid '+C.bd2+';background:'+C.bg2+';color:'+C.dim+';border-radius:9px;padding:8px;font-size:13px;font-weight:600;cursor:pointer;font-family:var(--sans);">Sell price</button></div>'
   +'<div id="_cPctRow">'+_calcInputBare('+','_cExitPct','10','%')+'</div>'
