function cp(){document.getElementById('applyBtn').disabled=true;document.getElementById('pending').style.display='none';}
const g=id=>document.getElementById(id).checked;

function sp1(el,gid,fk){document.querySelectorAll(`#${gid} .pill`).forEach(p=>p.classList.remove('on'));el.classList.add('on');F[fk]=el.dataset.v;if(fk==='days')F.daysMin=0;if(fk==='cap'&&typeof _liqSave==='function')_liqSave();mp();dots();}

// Dual-handle range slider: keeps the two handles ordered, updates the fill bar,
// labels, and the F min/max state, then re-applies filters.
function syncDual(which){
  const lo=document.getElementById(which+'Lo'), hi=document.getElementById(which+'Hi');
  let a=parseInt(lo.value), b=parseInt(hi.value);
  if(a>b){const t=a;a=b;b=t;} // keep ordered
  const loVal=RANGE_STOPS[a], hiVal=RANGE_STOPS[b];
  F[which+'Lo']=loVal;
  F[which+'Hi']=hiVal;
  // fill bar between the two handles
  const fill=document.getElementById(which+'Fill');
  fill.style.left=(a/8*100)+'%';
  fill.style.right=((8-b)/8*100)+'%';
  // labels
  const lbl=v=>v===0?'0%':v===Infinity?'Any':v+'%';
  document.getElementById(which+'LoL').textContent=lbl(loVal);
  document.getElementById(which+'HiL').textContent=hiVal===Infinity?(loVal===0?'Any':'∞'):hiVal+'%';
  mp();dots();
}

function syncP(){
  // Hidden pMin/pMax inputs hold the source of truth; sync F from them.
  const pmn=document.getElementById('pMin'), pmx=document.getElementById('pMax');
  if(!pmn||!pmx)return; // filters live in the Refine overlay; skip if not in DOM yet
  const mn=parseFloat(pmn.value)||0;
  const mx=parseFloat(pmx.value);
  F.pMin=mn;F.pMax=isNaN(mx)?500:mx;
}
// A price band pill was clicked → set the hidden min/max + clear typed boxes.
function setPriceBand(el){
  document.querySelectorAll('#gPrice .pill').forEach(p=>p.classList.remove('on'));
  el.classList.add('on');
  document.getElementById('pMin').value=el.dataset.lo;
  document.getElementById('pMax').value=el.dataset.hi;
  document.getElementById('pMinNum').value='';
  document.getElementById('pMaxNum').value='';
  syncP();mp();
}
// Typed exact $ range → overrides the band pills.
function priceNumIn(){
  const lo=parseFloat(document.getElementById('pMinNum').value);
  const hi=parseFloat(document.getElementById('pMaxNum').value);
  document.getElementById('pMin').value=isNaN(lo)?0:lo;
  document.getElementById('pMax').value=isNaN(hi)?500:hi;
  // deselect band pills, since a custom range is now in force
  document.querySelectorAll('#gPrice .pill').forEach(p=>p.classList.remove('on'));
  if(isNaN(lo)&&isNaN(hi)){const any=document.querySelector('#gPrice .pill[data-lo="0"][data-hi="500"]');if(any)any.classList.add('on');}
  syncP();mp();
}
// Hidden vMin/vMax retained for compatibility; absolute volume is now button + exact box driven.
function syncV(){
  // no-op visual sync; F.vMinAbs/vMaxAbs are the source of truth set by buttons/boxes
}
// A volume band button was clicked → set min shares, clear exact boxes.
function setAbsVolBand(el){
  document.querySelectorAll('#gAbsVol .pill').forEach(p=>p.classList.remove('on'));
  el.classList.add('on');
  F.vMinAbs=parseInt(el.dataset.min)||0;
  F.vMaxAbs=Infinity;
  const mn=document.getElementById('vMinNum'),mx=document.getElementById('vMaxNum');
  if(mn)mn.value='';if(mx)mx.value='';
  mp();dots();
}
function resetAbsVolBand(){
  F.vMinAbs=0;F.vMaxAbs=Infinity;
  const mn=document.getElementById('vMinNum'),mx=document.getElementById('vMaxNum');
  if(mn)mn.value='';if(mx)mx.value='';
  document.querySelectorAll('#gAbsVol .pill').forEach(p=>p.classList.remove('on'));
  const any=document.querySelector('#gAbsVol .pill[data-min="0"]');if(any)any.classList.add('on');
}
// Exact number typed → overrides the band buttons.
function volNumIn(){
  const minRaw=document.getElementById('vMinNum').value.trim();
  const maxRaw=document.getElementById('vMaxNum').value.trim();
  F.vMinAbs=minRaw===''?0:Math.max(0,parseInt(minRaw)||0);
  F.vMaxAbs=maxRaw===''?Infinity:Math.max(0,parseInt(maxRaw)||0);
  document.querySelectorAll('#gAbsVol .pill').forEach(p=>p.classList.remove('on'));
  if(minRaw===''&&maxRaw===''){const any=document.querySelector('#gAbsVol .pill[data-min="0"]');if(any)any.classList.add('on');}
}
function fmtVol(n){return n>=1e9?(n/1e9).toFixed(2)+'B':n>=1e6?(n/1e6).toFixed(2)+'M':n>=1e3?(n/1e3).toFixed(0)+'K':String(n);}
function inBands(val,set){if(set.has('all'))return true;for(const b of set){const[lo,hi]=b.split(':').map(Number);if(val>=lo&&val<hi)return true;if(hi>=9999&&val>=lo)return true;if(lo<=-999&&val<hi)return true;}return false;}

function rstBand(gid,fkey){document.querySelectorAll(`#${gid} .pill`).forEach(p=>p.classList.remove('ms-on','on'));document.querySelector(`#${gid} .pill[data-v="all"]`).classList.add('ms-on');F[fkey]=new Set(['all']);}
function rst1(gid,v,fk){document.querySelectorAll(`#${gid} .pill`).forEach(p=>p.classList.remove('on'));const el=document.querySelector(`#${gid} .pill[data-v="${v}"]`);if(el)el.classList.add('on');F[fk]=v;if(fk==='cap'&&typeof _liqSave==='function')_liqSave();}
