// Buying Volume Streak pill → set F.buyDays (0=off, 1–5 = min consecutive days).
function setBuyDays(n){
  F.buyDays=n|0;
  document.querySelectorAll('#gBuyDays .pill').forEach(p=>p.classList.remove('on'));
  const sel=document.querySelector(`#gBuyDays .pill[data-b="${F.buyDays}"]`);if(sel)sel.classList.add('on');
  // buying-streak needs the per-share series; if it's missing, load it first.
  if(F.buyDays>0 && !allData.some(s=>Array.isArray(s.series))){
    const st=document.getElementById('loadStatus');
    if(st)st.innerHTML='Loading price/volume history for buying-streak…';
    bulkVolume().then(()=>{mp();dots();applyF();maybeAutoMyReport();try{refreshBulkReady();}catch(e){}if(prepAllOn())setTimeout(()=>prepareAllSignals(true),600);else if(autoTechOn())setTimeout(autoRunTechnicals,700);});
  }else{
    mp();dots();
  }
}
