function sb(k){if(sortKey===k)sortDir*=-1;else{sortKey=k;sortDir=k==='ticker'||k==='name'?1:-1;}document.getElementById('sortSel').value=k;render();}

// ═══════════════════════════════════
//  WATCHLIST — star stocks (session memory)
