// ── Paper trading ────────────────────────────────────────────────────────────
// Practise buying and selling with virtual money. Holdings and a 1-year trade
// history persist locally. Prices come from the loaded end-of-day data, so the
// portfolio updates each time the day's data loads. Simulated fills at the last
// close — a practice tool, not real trading and not advice.
// Trading days held: counts weekdays (Mon–Fri) after the buy date up to and
// including the end date. Public holidays aren't excluded (no holiday calendar
// in end-of-day data), so counts can run 1–2 high across holiday periods.
const _tdhCache=new Map(); // v364: memoised — the portfolio calls this for every row + every stats pass; on a big history the repeated day-walk was a freeze-level cost
function tradingDaysHeld(a,b){
  const k=a+'|'+b;
  const hit=_tdhCache.get(k); if(hit!==undefined)return hit;
  let d=new Date(a);const end=new Date(b);
  if(!isFinite(d)||!isFinite(end)||end<=d)return 0;
  let n=0;
  while(d<end){d=new Date(d.getTime()+86400000);const w=d.getDay();if(w!==0&&w!==6)n++;if(n>2000)break;}
  if(_tdhCache.size>8000)_tdhCache.clear();
  _tdhCache.set(k,n);
  return n;
}
const PAPER_STORE='asxScreener.paperTrades.v1';
// ═══ v312 — the 🤖 Auto-pilot trades its OWN practice account ($50k) ═══
const PAPER_STORE_AUTO='asxScreener.paperTrades.auto.v1';
const AP_START_CASH=50000;
window._pfCtx=window._pfCtx||'main'; // which account the UI is looking at
// v408: ONE practice account PER EXCHANGE. ASX keeps the original storage keys
// (nobody's existing account moves); every other exchange gets its own store —
// its own cash, its own history — so a NYSE buy (USD) can never draw from the
// ASX (AUD) pot. First open of a non-ASX exchange migrates that exchange's old
// records out of the shared store (see _pfSplitMigrate).
const PF_EXCHS_KEY='asxScreener.paperExchs.v1';
function _pfExch(exch){ const e=String(exch||currentExch||'ASX').toUpperCase(); return e||'ASX'; }
function _pfExchsKnown(){
  try{ const l=JSON.parse(localStorage.getItem(PF_EXCHS_KEY)||'[]');
    const s=['ASX']; (Array.isArray(l)?l:[]).forEach(e=>{ if(e&&s.indexOf(e)<0)s.push(e); }); return s;
  }catch(e){ return ['ASX']; }
}
function _pfExchRegister(ex){
  try{ if(!ex||ex==='ASX')return; const l=JSON.parse(localStorage.getItem(PF_EXCHS_KEY)||'[]');
    const a=Array.isArray(l)?l:[]; if(a.indexOf(ex)<0){ a.push(ex); localStorage.setItem(PF_EXCHS_KEY,JSON.stringify(a)); }
  }catch(e){}
}
// v409: the portfolio tabs read PER-EXCHANGE accounts, but _paper() alone
// defaults to the exchange whose market data is loaded — so a row shown in the
// portfolio can live in a DIFFERENT store than _paper() returns. Every action
// on an existing row (undo, sell, target, delete, cancel…) must therefore first
// find the store its item actually lives in: viewed trading account first, then
// the other, across ASX + every registered exchange.
function _pfFindStore(test){
  const a0=(window._pfCtx==='auto')?'auto':'main';
  const accts=[a0,(a0==='auto')?'main':'auto'];
  const exchs=_pfExchsKnown();
  for(const a of accts){ for(const ex of exchs){
    let pp=null,r=null;
    try{ pp=_paper(a,ex); r=test(pp); }catch(e){}
    if(r) return {p:pp,acct:a,exch:ex,hit:r};
  } }
  return null;
}
function _pfKey(acct,exch){
  const base=((acct||window._pfCtx)==='auto')?PAPER_STORE_AUTO:PAPER_STORE;
  const ex=_pfExch(exch);
  return ex==='ASX'?base:base+'.'+ex;
}
window._pfSwitch=function(k){ window._pfCtx=(k==='auto')?'auto':'main'; try{updatePaperPrices();}catch(e){} try{showPortfolio(window._pfExSel||'ALL');}catch(e){} };
// Run an account-aware engine for BOTH accounts, sequentially, without ever
// flipping the global view context (async-safe: a user click mid-engine can
// never land in the wrong account).
async function _bothPortfolios(fn){
  let out=[];
  try{ const a=await fn('main'); if(Array.isArray(a))out=out.concat(a); }catch(e){}
  try{ const b=await fn('auto'); if(Array.isArray(b))out=out.concat(b); }catch(e){}
  return out;
}
const PAPER_START_CASH=10000;
// ── Optional brokerage simulation: a flat fee per transaction (buy or sell),
