    lockLadderOn:(r.lockLadderOn===true), lockStep:Math.min(25,Math.max(1,num(r.lockStep,5))), lockMargin:Math.min(15,Math.max(0,num(r.lockMargin,3))), // v514: 🔒 profit ladder
    apOn:(fresh?true:(r.apOn===true)), /* v797: the robot defaults ON for brand-new accounts — Tony's decision 16 Aug. Practice money only; a clear OFF switch sits on the Starter Automation card and in bot settings. Saved accounts keep their exact state. */ apSource:(function(v){ if(v==='best')return 'best'; try{ return (_AP_SRC_KEYS.indexOf(v)>=0)?v:'best'; }catch(e){ return (v==='top20')?'top20':'best'; } })(r.apSource), apProvenOnly:(fresh?true:(r.apProvenOnly===true)),
    apMinScore:num(r.apMinScore,fresh?7:0), apMinPrice:num(r.apMinPrice,fresh?0.20:0), apMaxPrice:num(r.apMaxPrice,fresh?1.99:0), apQuietOnly:(r.apQuietOnly===true), /* v747: fresh installs carry the All-rounder band ($0.20-$1.99 — ten-year decomposition: dropping sub-20c and raising the ceiling to $1.99 each helped independently) + the score-7 harness every preset was measured under */
    apMaxBuys:Math.max(1,Math.min(6,Math.round(num(r.apMaxBuys,fresh?4:1)))),
    apAmt:num(r.apAmt,0), apGreenOnly:(fresh||r.apGreenOnly===true), apNoChaseRsi:(fresh||r.apNoChaseRsi===true), apMaxChasePct:num(r.apMaxChasePct,fresh?8:0), apCombo:(typeof r.apCombo==='string'&&r.apCombo?r.apCombo:(fresh?'card-good':'')), apEntry:(r.apEntry==='dip'?'dip':(fresh?'dip':'open')), apDipPct:Math.min(50,num(r.apDipPct,fresh?2:0)), /* v744: 2% dip entry — the ten-year ladder showed 5% starves the entry (lesson 55's method applied to the dip) */
    apLadder:(fresh?true:(r.apLadder===true)),
