    scaleOut:(fresh?true:(r.scaleOut===true)), scaleOutPct:Math.min(90,Math.max(10,num(r.scaleOutPct,50))), // v384: 🎯 scale-out — sell part at target, runner rides the trail
    apSignals:(Array.isArray(r.apSignals)?r.apSignals.filter(k=>['bo','inf','inst','cx','dir','vr','blk'].indexOf(k)>=0):[]),
