// The worker's nightly saved-rules lane decides with whatever blob it holds,
// so every successful save mirrors the bot-relevant numbers up. apOn ON =
// mirror the rules; apOn OFF = clear the blob, so the server lane never
// keeps deciding for a bot the person has switched off. Fire-and-forget,
// 8s timeout, all failures silent - an old worker (pre-w505) 404s and
// nothing changes anywhere. The access key rides the global fetch wrapper.
function _botRulesMirror(r){
  try{
    const b=_gateBase(); if(!b)return;
    const ctl=(typeof AbortController==='function')?new AbortController():null;
    const t=setTimeout(function(){ try{ if(ctl)ctl.abort(); }catch(e){} },8000);
    let body;
    if(r&&r.apOn===true&&r.enabled!==false){
      const num=function(v){ const x=+v; return isFinite(x)?x:0; };
      const amt=num(r.apAmt);
      body={
        trailPct:num(r.trailPct), targetPct:num(r.targetPct), stopPct:num(r.stopPct),
        dipPct:(r.apEntry==='dip'?Math.min(15,num(r.apDipPct)):0),
        minScore:Math.min(10,num(r.apMinScore)), topN:Math.max(1,Math.min(6,Math.round(num(r.apMaxBuys)||1))),
        minPrice:(num(r.apMinPrice)>=0.01?num(r.apMinPrice):0.01),
        maxPrice:(num(r.apMaxPrice)>0.01?Math.min(50,num(r.apMaxPrice)):50),
        amount:(amt>=2000?Math.min(5000,amt):2000)   /* v816: $2,000 floor \u2014 $6 flat brokerage makes smaller parcels uneconomic by construction; matches the server validator (w534), which rejects below it */
      };
    } else body={clear:true};
    fetch(b+'/bot/rules',{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify(body),signal:(ctl?ctl.signal:undefined)})
      .then(function(res){ clearTimeout(t); return res&&res.ok?res.json():null; })
      .then(function(j){ try{ window._botRulesMirrorLast=(j&&j.ok)?(j.cleared?'cleared':'saved'):'unsupported'; }catch(e){} })
      .catch(function(){ clearTimeout(t); });
  }catch(e){}
}
// ═══ v304 — three ready-made rule sets (fill the form; the user still saves) ═══
// Updated per the 31 Jul 2026 evidence session: target/stop/trail/breakeven/hold
// replaced with the tested values (15/15 fixed as the All-rounder centre,
// 10/15 and 20/15 as the Defender/Hunter spread; trail, breakeven, and hold
// all set to 0/off, since a plain target/stop beat the app's own trailing
// mechanism head-to-head on identical entries). maxPos, maxN, green, rsi,
// and chase were not part of that evidence and are left exactly as they were.
// v641 — the three rule sets, rebuilt from the 1 August 2026 evidence session.
// All three now carry their OWN entry and price band, because the testing showed
// those are not separable from the exit: the same exit rule performs very
// differently depending on which band it is fed. Every number below comes from
// the same head-to-head run — full ~2.9 years of stored history, $100k across 10
// positions, top 4 a day at score 7+, after $3-a-side brokerage and slippage.
//
//   🛡 Defender    15% target / 15% stop, $0.20-$0.99 ..... +45.7%, 67.7% win rate
//   ⚖ All-rounder  20% target / 15% stop, $0.15-$1.75 ..... +69.5%  [band re-set to $0.20-$1.99 in v747 — see below], 62.5% win rate
//   ⚡ Hunter       20% TRAILING stop, no target, $0.20-$0.99  +145.5%, 50.8% win
//
// v745: ten-year re-check (13 Aug 2026, real OHLC fills, 2% dip) confirmed every
// OTHER dial: Defender 15/15 is the peak on its own objective (win 64.1%,
// DD -8.5%, losing run 11 — both alternatives worse on all three); All-rounder
// 20/15 is the balanced peak (25/15 adds return but trades away win rate,
// drawdown and run length); Hunter 20% trail is the robustness peak (+232%,
// +160% without its top three, vs +106% woTop3 at 30% with double the DD).
// The 1-Aug figures above are kept for history: they are 2.9-year, 5%-dip numbers.
// v747: All-rounder band re-set $0.15-$1.75 -> $0.20-$1.99 on the ten-year
// decomposition at 2% dip: dropping the sub-20c tail (+22pts) and raising the
// ceiling to $1.99 (+20pts) helped INDEPENDENTLY; together +85.4% with +71.7%
// after removing the top three, DD -7.7%, losing run 12 (was +58.3%/+32.9%/
// -9.5%/20). Neighbours strong, 0.25 floor collapses it - a plateau with a
// known edge. Hunter and Defender tested STRICTLY WORSE widened; unchanged.
// Every one uses the 2% dip entry — a patient limit 2% under the reference
// close. v744: was 5% for years; the ten-year replay showed the deeper dip
// MISSES winners rather than filtering losers (130 signals offered at 2%,
// only 84 at 5%) and returns fall monotonically from 2% to 10%.
// — which beat buying at market in every band and every exit rule tested.
//
// Hunter is the strongest and the hardest to hold: about half its trades lose,
// positions run ~50 days instead of days, and every winner gives back 20% from
// its peak on the way out. Stress-tested to 2% slippage it still returned
// +124.5%, and its worst fall from a high was about -8%, but it spent 10 trades
// in a row below a previous high — that stretch is where rules get abandoned.
//
// The bands differ per preset on purpose and this is the weakest part of the
// evidence: each band is the one that suited THAT exit best over ONE window on
// ONE market. Treat the exits as well-tested and the bands as best-available.
const RULE_PRESETS={
  def:{label:'🛡 Defender',   tgt:15, stop:15, maxPos:8,  maxN:20, trail:0,  be:0, hold:0, green:true, rsi:true,  chase:5,  dip:2, minPx:'0.20', maxPx:'0.99'}, /* v781: maxN 20 on Tony's instruction — a ceiling; the gates rarely fill it */
  all:{label:'⚖ All-rounder', tgt:20, stop:15, maxPos:10, maxN:20, trail:0,  be:0, hold:0, green:true, rsi:true,  chase:8,  dip:2, minPx:'0.20', maxPx:'1.99'},
  hun:{label:'⚡ Hunter',     tgt:0,  stop:0,  maxPos:10, maxN:20, trail:20, be:0, hold:0, green:true, rsi:false, chase:10, dip:2, minPx:'0.20', maxPx:'0.99'}
};
window.applyRulePreset=function(k){
  const p=RULE_PRESETS[k]; if(!p)return;
  const set=(id,v)=>{ const el=document.getElementById(id); if(el)el.value=v; };
  const tick=(id,v)=>{ const el=document.getElementById(id); if(el)el.checked=!!v; };
  set('rTgt',p.tgt); set('rStop',p.stop); set('rMaxPos',p.maxPos); set('rMaxN',p.maxN);
  set('rTrail',p.trail); set('rBE',p.be); set('rHold',p.hold);
  tick('rApGreen',p.green); tick('rApRsi',p.rsi); set('rApChase',p.chase);
  // v641 — the entry and the price band travel WITH the preset now. Leaving
  // them behind was how a preset could be "applied" and still trade a different
  // universe than the one it was measured on.
  if(p.dip!=null){ set('rApEntrySel','dip'); set('rApDip',p.dip); }
  if(p.minPx!=null) set('rApMinPx',p.minPx);
  if(p.maxPx!=null) set('rApMaxPx',p.maxPx);
  const m=document.getElementById('rulesMsg');
  if(m)m.textContent=p.label+' filled in — press 💾 Save my rules to keep it.';
  try{_paintPresetChips();}catch(e){}
};
// v317 — the gold chip is COMPUTED, not hardcoded: whichever preset exactly
// matches the numbers+gates in the form is highlighted; otherwise none is
// ("your own custom mix"). Fixes "running Hunter but it shows All-rounder".
window._paintPresetChips=function(){try{
  const g=id=>{const el=document.getElementById(id);return el?+el.value:NaN;};
  const c=id=>{const el=document.getElementById(id);return el?!!el.checked:false;};
  let match='';
  for(const k in RULE_PRESETS){const p=RULE_PRESETS[k];
    // v641 — the dip and the band are part of the preset now, so they are part
    // of the match. Without this a correctly applied preset would light no chip.
    const sv=id=>{const el=document.getElementById(id);return el?String(el.value):'';};
    const bandOk=(p.minPx==null||+sv('rApMinPx')===+p.minPx)&&(p.maxPx==null||+sv('rApMaxPx')===+p.maxPx);
    const dipOk=(p.dip==null)||(sv('rApEntrySel')==='dip'&&g('rApDip')===p.dip);
    if(g('rTgt')===p.tgt&&g('rStop')===p.stop&&g('rMaxPos')===p.maxPos&&g('rMaxN')===p.maxN&&g('rTrail')===p.trail&&g('rBE')===p.be&&g('rHold')===p.hold&&c('rApGreen')===p.green&&c('rApRsi')===p.rsi&&g('rApChase')===p.chase&&bandOk&&dipOk){match=k;break;}}
  [['def','pcDef'],['all','pcAll'],['hun','pcHun']].forEach(function(pr){
    const b=document.getElementById(pr[1]); if(!b)return; const on=match===pr[0];
    b.style.border='1px solid '+(on?'var(--gold)':'var(--border)');
    b.style.background=on?'rgba(255,210,0,.10)':'var(--bg4)';
    b.style.color=on?'var(--gold)':'var(--text)';
  });
  const cap=document.getElementById('pcCap');
  if(cap)cap.innerHTML=match?('The numbers below = <b>'+RULE_PRESETS[match].label+'</b> (highlighted).'):'The numbers below are your own custom mix — no preset highlighted.';
}catch(e){}};
