// Refresh each holding's last-known price from the currently loaded data,
// then record today's portfolio-value snapshot (one per date, kept ~1 year)
// so the portfolio builds its own day-by-day history over time.
function updatePaperPrices(acct){
  const ACCT=acct||window._pfCtx;
  const p=_paper(ACCT);let changed=false;
  // v364: one Map instead of allData.find per holding (O(1) lookups)
  const _adm=new Map();(allData||[]).forEach(x=>{_adm.set(x.ticker+'|'+x.exchange,x);});
  (p.holdings||[]).forEach(h=>{
    const s=_adm.get(h.ticker+'|'+h.exchange);
    if(s&&s.price>0){h.lastPrice=s.price;h.lastDate=(s._q&&s._q.d)||_todayLocal();changed=true;}
  });
  // 🎯 Auto-sell targets are checked by checkAutoSellTargets() (async), which
  // uses each day's intraday HIGH — sells if the price reached the target at
  // ANY time during a day, like a real limit order. See below.
  // Daily value snapshot (only when holding something) — overall and per exchange.
  if((p.holdings||[]).length){
    const today=_todayLocal();
    const cutoff=new Date(Date.now()-365*86400000).toISOString().slice(0,10);
    let inv=0,val=0;const byEx={};
    p.holdings.forEach(h=>{
      const hv=h.qty*(h.lastPrice||h.buyPrice);
      inv+=h.invested;val+=hv;
      (byEx[h.exchange]=byEx[h.exchange]||{inv:0,val:0}).inv+=h.invested;
      byEx[h.exchange].val+=hv;
    });
    const upsert=(arr,snap)=>{const ex=arr.findIndex(x=>x.d===snap.d);if(ex>=0)arr[ex]=snap;else arr.push(snap);return arr.filter(x=>x.d>=cutoff);};
    p.valueHistory=upsert(p.valueHistory||[],{d:today,inv:+inv.toFixed(2),val:+val.toFixed(2),eq:+((p.cash||0)+_reservedSum(p)+val).toFixed(2)}); // v379: eq = FULL account value (cash + reserved-in-pending-orders + holdings), so the day-by-day chart matches the account total — was dropping money reserved in pending orders
    p.vhByEx=p.vhByEx||{};
    Object.keys(byEx).forEach(ex=>{
      p.vhByEx[ex]=upsert(p.vhByEx[ex]||[],{d:today,inv:+byEx[ex].inv.toFixed(2),val:+byEx[ex].val.toFixed(2)});
    });
    changed=true;
  }
  if(changed)_paperSave(p,ACCT);
  if(typeof refreshPortfolioBtn==='function')refreshPortfolioBtn();
}
// 🎯 Intraday auto-sell: for each holding with a target, fetch its daily OHLC
