  // v366: don't trust the transient _pfCtx (the auto-pilot flips it while it runs) AND don't
  // rely on the exact sell-date (a re-recorded trade can shift it). Find the trade in the
  // viewed account then the other account, matching exact first, then by ticker + buy-date.
  const _fT=(pp)=>{ const H=pp.history||[]; let i=H.findIndex(t=>t.sellDate===sellDate&&t.ticker===ticker&&t.buyDate===buyDate);
    if(i<0){ // v368: no exact sell-date (it can drift); among same ticker+buy-date trades pick the CLOSEST sell-date so a part-sold lot can't match the wrong day
      let _b=-1,_bd=Infinity; for(let k=0;k<H.length;k++){ const t=H[k]; if(t&&t.ticker===ticker&&t.buyDate===buyDate){ const _d=Math.abs(new Date(t.sellDate||0)-new Date(sellDate||0)); if(_d<_bd){_bd=_d;_b=k;} } } i=_b;
    } return i; };
