  // v409: auto-sold trades can sit in EVERY exchange's account — gather and restore across all of them.
  const stores=_pfExchsKnown().map(function(ex){ const q=_paper(undefined,ex);
    return {ex:ex,p:q,autos:(q.history||[]).map(function(t,i){return {t:t,i:i};}).filter(function(x){return x.t&&x.t.auto;})};
  }).filter(function(s){return s.autos.length>0;});
  if(!stores.length){ alert('There are no auto-sold trades to restore in this account.'); return; }
  const nAll=stores.reduce(function(a,s){return a+s.autos.length;},0);
  const total=stores.reduce(function(a,s){return a+s.autos.reduce(function(b,x){return b+(x.t.proceeds||0);},0);},0);
  const cur=(stores[0].autos[0].t.currency)||'AUD';
  if(!confirm(`Restore all ${nAll} auto-sold position${nAll>1?'s':''}?\n\nThis returns every auto-sold holding to your portfolio and reverses ${fmtP(total,cur)} of sale proceeds back out of your cash. Auto-sell is then PAUSED on each restored position so a rule can't sell it straight back — it stays put until you set a 🎯 target or 🛑 stop on it (which hands that one back to your rules). Your global rules are unchanged.`))return;
  let n=0;
