// Create/update a watchlist from the portfolio's current holdings (respects
// the selected exchange tab). Uses live screener data where loaded, else a
// snapshot from the holding itself.
function savePortfolioToWatch(){
  const {ex,hold}=_paperFiltered();
  if(!hold.length){alert('No holdings'+(ex==='ALL'?'':' on '+ex)+' to add — buy something first.');return;}
  const dflt='Portfolio '+(ex==='ALL'?'All':ex)+' '+new Date().toLocaleDateString('en-AU');
  const name=prompt('Save these '+hold.length+' holding'+(hold.length===1?'':'s')+' to which watchlist?\n\nType a name (existing or new):',dflt);
  if(name===null||!name.trim())return;
  const nm=name.trim();
  if(!watchlists[nm])watchlists[nm]={};
  let added=0;
  hold.forEach(h=>{
    if(watchlists[nm][h.ticker])return;
    const s=allData.find(x=>x.ticker===h.ticker&&x.exchange===h.exchange);
    watchlists[nm][h.ticker]=s?JSON.parse(JSON.stringify(s))
      :{ticker:h.ticker,name:h.name||'',exchange:h.exchange,currency:h.currency,
        price:h.lastPrice||h.buyPrice,chgPct:0,chgAbs:0,volume:0,lastDate:h.lastDate||''};
    added++;
  });
  activeWatch=nm;
  saveWatchlists();updateWatchBtn();
  alert(`Added ${added} share${added===1?'':'s'} to “${nm}”. Open it via the ★ watchlist button.`);
}

