// Log out: reloads so the password gate re-locks the app. Data stays saved.
// v415: 👤 Account menu — password, language, updates and log out in one tidy place
window.toggleAcctMenu=function(ev){
  try{ev.stopPropagation();}catch(e){}
  var m=document.getElementById('acctMenu'); if(!m)return;
  var open=m.style.display!=='none';
  m.style.display=open?'none':'block';
  if(!open){
    try{ var v=document.getElementById('acctMenuVer'); if(v)v.textContent='Insight Trading · v'+APP_VERSION; }catch(e){}
    // v708 - the menu is right-anchored to the button, which on phones sits near
    // the LEFT edge, so the panel hung off-screen with its first letters clipped.
    // Clamp it into the viewport after opening.
    try{
      m.style.right='0'; m.style.left='auto'; m.style.maxWidth=Math.min(300,window.innerWidth-16)+'px';
      var r=m.getBoundingClientRect();
      if(r.left<8){
        var pr=(m.offsetParent||document.body).getBoundingClientRect();
        m.style.right='auto'; m.style.left=(8-pr.left)+'px';
        var r2=m.getBoundingClientRect();
        if(r2.right>window.innerWidth-8) m.style.left=(8-pr.left-(r2.right-(window.innerWidth-8)))+'px';
      }
    }catch(e){}
    setTimeout(function(){document.addEventListener('click',function(e){ if(!m.contains(e.target))m.style.display='none'; },{once:true});},0);
  }
};
function logout(){
  if(!confirm('Log out? You will need your app password to get back in. Your saved data (watchlists, key) is kept.'))return;
  location.reload();
}
