// The Evidence tiles promise an honest zero. That promise is only kept for
// shares that were actually tested. This line names the ones that weren't.
function _evSetNote(el,htmlTxt,tip){
  if(!el)return;
  if(!htmlTxt){ el.style.display='none'; el.innerHTML=''; el.removeAttribute('title'); el.removeAttribute('data-ttip'); return; }
  el.style.display='block'; el.innerHTML=htmlTxt; el.setAttribute('title',tip);
  try{ if(typeof privateOn==='function'&&privateOn()){ el.dataset.ttip=tip; el.removeAttribute('title'); } }catch(e){}
  try{_radarCompactSync();}catch(e){} // v518: keep the compact evidence sentence current
}
function _evFoldPref(){ return !!window._evFoldOpenNow; } /* v605: in-memory ONLY, never persisted — always starts false on a fresh load. v601's localStorage version remembered a single tap forever, silently, which read as 'stuck open' three releases in a row */
function _evFoldSet(open){ window._evFoldOpenNow=!!open; try{ _evFoldApply(); }catch(e){} }
function _evFoldApply(){
  /* v601 — a thin visibility layer over the (already-built) long explanation.
     Never touches _evSkipNote's own text-building — only decides which of
     the long text or the short summary the user actually sees right now. */
  try{
    var full=document.getElementById('evRuleNote'), shortEl=document.getElementById('evShort'); /* v607 ROOT CAUSE: this was 'evSkipNote' — the WRONG element. The actual long paragraph ('SIGNALS 19 graded... one ruler... prove it') is written to 'evRuleNote' via the _rn variable — a completely separate element the fold never touched across v601-v605. evSkipNote holds a DIFFERENT thing (the checking/failed status messages), correctly left alone: those are actionable notices, not the explanatory wall of text being folded here. */
    if(!full||!shortEl)return;
    var hasContent=!!(full.innerHTML&&full.innerHTML.length>0); /* v602 fix: check the CONTENT, not display style — this same function is what flips that style off, so using it to detect 'anything to show' was self-defeating after the first collapse */
    if(!hasContent){ shortEl.style.display='none'; return; }
    var open=_evFoldPref();
    if(open){
      full.style.display='block';
      shortEl.innerHTML='<span onclick="_evFoldSet(false)" style="color:var(--gold);cursor:pointer;text-decoration:underline dotted;">▾ hide</span>';
      shortEl.style.display='block';
      return;
    }
    full.style.display='none';
    var lc=(typeof _evLineCounts==='function')?_evLineCounts():null;
    var solN=(document.getElementById('sEvS')&&document.getElementById('sEvS').textContent)||'–';
    var proN=(document.getElementById('sEvP')&&document.getElementById('sEvP').textContent)||'–';
    var npN=(document.getElementById('sEvE')&&document.getElementById('sEvE').textContent)||'–';
    shortEl.innerHTML='🧪 '+solN+' solid · '+proN+' promising · '+npN+' not proven <span onclick="_evFoldSet(true)" style="color:var(--gold);cursor:pointer;text-decoration:underline dotted;margin-left:4px;">▸ why</span>';
    shortEl.style.display='block';
  }catch(e){}
}
function _evSkipNote(ready,nLiq,nHist,nSeen,nThin,nNeg){
  var el=document.getElementById('evSkipNote');
  var sg=document.getElementById('sigSkipNote');
  // v471b — BEFORE the not-ready return, not after it. "Not ready" is exactly
  // what an unreachable server looks like, so the state with the emptiest
  // screen was the one state that explained nothing.
  try{
    var _noYear=(window._scanSrc==='unavailable'), _noDay=(window._scanSrc!=='unavailable'&&!_scDayGet());
    /* v589 — "hasn't been tried yet" is NOT "tried and failed". On a fresh
       load the day-signal answer simply hasn't ARRIVED yet, but this branch
       used to dress that instant in the failure clothes ('try again') — a
       false alarm on every single open. The failure note now requires a
       CONCLUDED failure: the server latched unavailable, the warm ended in
       'failed', or a recorded _gradeFail. Until one of those is true, the
       gap shows an honest in-flight message with the live ticking timer. */
    var _tried=_noYear||window._warmState==='failed'||!!window._gradeFail;
    if((_noYear||_noDay)&&!_tried){
      if(!window._evBootAt){
        window._evBootAt=Date.now();
        /* v596 — the v595 watchdog only fired by being RE-CHECKED inside
           statsBar(), which itself only runs off the 2s heartbeat interval.
           A backgrounded browser tab (Tony's 'second screen' — a second
           window/tab without focus) gets that interval throttled by the
           browser, sometimes to once a minute or less, so the recheck could
           be starved indefinitely: the display freezes at whatever second it
           last painted while real time keeps passing. A ONE-SHOT setTimeout
           scheduled here, independent of any polling loop, does not depend
           on the heartbeat ever firing again — it converts the state itself
           the moment 150s elapses, exactly like _evAutoRetry's own retry
           timer already does successfully. */
        try{
          var _bootAt=window._evBootAt;
          setTimeout(function(){
            try{
              if(window._evBootAt===_bootAt&&!window._gradeFail){
                window._gradeFail={kind:'timeout',at:Date.now(),ms:150000,msg:'no answer and no error after 150 seconds'};
                window._warmState='failed'; window._evBootAt=null;
                _evAutoRetry();
                if(typeof statsBar==='function')statsBar();
              }
            }catch(e7){}
          },150000);
        }catch(e6){}
      }
      /* the polling recheck stays too, as a belt-and-braces path for tabs
         that ARE getting repainted (it will simply find _gradeFail already
         set by the timer above and skip straight to the failed branch). */
      if(Date.now()-window._evBootAt>150000&&!window._gradeFail){
        window._gradeFail={kind:'timeout',at:Date.now(),ms:150000,msg:'no answer and no error after 150 seconds'};
        window._warmState='failed'; window._evBootAt=null;
        try{ _evAutoRetry(); }catch(e8){}
      }
      try{ _evPulseEnsure(true); }catch(e9){}
      _evSetNote(el,'\ud83e\uddea checking today\u2019s signals with our server\u2026'+_evElapsed(window._evBootAt),'The evidence tiles fill in when the server answers \u2014 usually a second or two once the day is warm, up to 30\u201390 seconds only if this is the very first grade of a new day or window. The timer is live: ticking means working. If it fails, this message will say so and the app will retry by itself.');
      _evSetNote(sg,'');
      return;
    }
    if(_noYear||_noDay){
      _evSetNote(el,_gradeFailText()+_evRetryCountdown()+'<button onclick="_evRetryServer()" style="border:1px solid var(--gold);color:var(--gold);background:rgba(255,210,0,.08);border-radius:6px;padding:1px 7px;font-weight:700;font-size:10px;font-family:var(--sans);cursor:pointer;margin-left:6px;">try again</button>'+((typeof _cardLiqKey==='function'&&_cardLiqKey()==='any')?'<button onclick="_evSetFloor(\'250k\')" style="border:1px solid var(--gold);color:var(--gold);background:transparent;border-radius:6px;padding:1px 7px;font-weight:700;font-size:10px;font-family:var(--sans);cursor:pointer;margin-left:4px;">set $250k first</button>':''),
        (_noYear&&_noDay)?'Both halves of the evidence system run on our server: the year-long replay that grades each signal, and the check of which signals are firing today. Neither could be reached just now, so these tiles are blank rather than wrong. Prices, volumes, your portfolio and your watchlists are stored on your device and are unaffected. Try again in a moment, or reload.'
        :(_noYear?'The year-long replay that grades each signal runs on our server, and it could not be reached just now. Rather than show tiers we cannot stand behind, the evidence tiles stay blank. Everything stored on your device \u2014 prices, volumes, portfolio, watchlists \u2014 is unaffected. Try again in a moment, or reload.'
                 :'Which signals are firing today is worked out on our server, so the thresholds behind them are not published in the app. We could not reach it just now, so these tiles are blank rather than wrong. Everything stored on your device is unaffected. Try again in a moment, or reload.'));
      _evSetNote(sg,'');
      return;
    }
  }catch(e){}
  if(!ready){ _evSetNote(el,''); _evSetNote(sg,''); return; }
  nNeg=nNeg||0;
  var bits=[], tip='';
  // v462: thin shares are INCLUDED and flagged. This line is not a warning
  // that something is missing — it is a warning about what IS there.
  if(nNeg){
    bits.push('\u26a0\ufe0f '+nNeg+' firing losing signals');
    tip+='\u26a0\ufe0f '+nNeg+' share'+(nNeg===1?' is':'s are')+' firing graded signals whose records UNDERPERFORM the market, so they earn no tier. A big sample can prove a signal reliably loses \u2014 that is good evidence about a bad signal, and the \ud83e\udd16 auto-pilot ignores them too. ';
  }
  if(nThin){
    bits.push('\ud83d\udca7 '+nThin+' thin \u00b7 checked &amp; flagged');
    tip+='\ud83d\udca7 '+nThin+' of the '+(nSeen||0)+' shares on screen trade below your \ud83d\udca7 floor ('+_cardLiqLabel()+') on three-month average turnover. Since v462 they ARE evidence-checked and counted here \u2014 hiding them told you less than warning you does \u2014 but they wear a \ud83d\udca7 on their \u2696\ufe0f chip, and the auto-pilot still will not buy them. Thin shares can be hard to get out of without moving the price against you. ';
  }
  // The only remaining EXCLUSION is a genuine data limit, not a policy.
  if(nHist){
    bits.push('\ud83d\udcc9 '+nHist+' need more history');
    tip+='\ud83d\udcc9 '+nHist+' share'+(nHist===1?' has':'s have')+' fewer than 30 stored days \u2014 not enough to test a signal on, so '+(nHist===1?'it is':'they are')+' not included in any count above. Run \u2b07 Download all to store more. ';
  }
  if(nLiq){   // defensive: nothing should set this since v462
    bits.push('\ud83d\udca7 '+nLiq+' not checked \u00b7 below your '+_cardLiqLabel()+' floor');
    tip+='\ud83d\udca7 '+nLiq+' share'+(nLiq===1?' is':'s are')+' below your grading floor ('+_cardLiqLabel()+') and were not tested. ';
  }
  if(!bits.length){ _evSetNote(el,''); _evSetNote(sg,''); return; }
  tip+='These describe WHAT WAS COUNTED \u2014 the difference between "we looked and found nothing" and "we never looked" is the whole point.';
  // v502 — one word of gutter label. Until now the ONLY thing telling a reader
  // that this line counts SHARES while the line under it counts SIGNALS was a
  // tooltip, and nobody hovers a tooltip to discover that two numbers are not
  // comparable. Two words do what a paragraph was failing to do.
  _evSetNote(el,'<b style="color:var(--dim);font-weight:800;letter-spacing:.4px">SHARES</b> '+bits.join(' \u00b7 '),tip);
  // The \ud83d\udd2c counts only need a denominator when something was genuinely EXCLUDED.
  var nOut=(nHist||0)+(nLiq||0), tested=Math.max(0,(nSeen||0)-nOut);
  if(nOut){
    _evSetNote(sg,'\ud83d\udd2c counts from '+tested+' of '+(nSeen||0)+' shares',
      'These counts only include the '+tested+' share'+(tested===1?'':'s')+' that could be evidence-checked. '+nOut+' of the '+(nSeen||0)+' on screen could not be'+(nHist?' ('+nHist+' with under 30 stored days)':'')+'. So a 0 here means "none of the checked shares is firing it" \u2014 NOT "no share is firing it".');
  } else {
    _evSetNote(sg,'');
  }
}

// Currency map
const EXCH_CUR={ASX:'AUD',NYSE:'USD',NASDAQ:'USD',AMEX:'USD',OTCBB:'USD',USMF:'USD',INDEX:'USD',FOREX:'USD',CC:'USD',LSE:'GBP',TSX:'CAD',TSXV:'CAD',NSE:'INR',SGX:'SGD',AMS:'EUR',BRU:'EUR',PAR:'EUR',OSL:'NOK',FRA:'EUR',MSE:'EUR',SHG:'CNY',SHE:'CNY'};

function guessType(name){
  const n=(name||'').toUpperCase();
  // Options / Warrants / Rights (derivatives & entitlements)
  if(/\bOPTION|\bOPT\b|\bWARRANT|\bWTS?\b|\bRIGHTS?\b|\bCALL\b|\bPUT\b|EXPIRING|\bEXP \d/.test(n))return'Option';
  // Preference shares / hybrids (check before generic "notes" so capital notes land here)
  if(/PREFERENCE|\bPREF\b|\bHYBRID|CAPITAL NOTE|RESET PREF|STEP-UP|CONVERTIBLE PREF/.test(n))return'Preference';
  // Bonds / Notes / convertible debt
  if(/\bNOTES?\b|\bBOND|CONVERTIBLE|\bDEBENTURE|FIXED RATE|FLOATING RATE|SUBORDINATED/.test(n))return'Bond';
  // REITs / property trusts
  if(/\bREIT\b|PROPERTY TRUST|PROPERTY GROUP|PROPERTY FUND|REAL ESTATE/.test(n))return'REIT';
  // ETFs
  if(/\bETF\b|EXCHANGE TRADED|BETASHARES|VANGUARD|ISHARES|SPDR|VANECK/.test(n))return'ETF';
  // Listed investment companies / trusts
  if(/INVESTMENT CO|LISTED INVEST|\bLIC\b|\bLIT\b/.test(n))return'LIC';
  return'Ordinary';
}

// ═══════════════════════════════════
//  CALC STREAKS — real consecutive up-days
//  Counts how many days in a row each stock CLOSED ABOVE the
//  previous day's close, using EODData daily history.
//  Runs only for the currently-filtered stocks (rate-limit friendly).
// ═══════════════════════════════════
const _histCache=new Map(); // session cache: exch|ticker|days → rows (speeds re-scans hugely)
function _histClearCache(){_histCache.clear();}
// fetch() with a hard timeout so a hung/never-responding request can't freeze
// the app. Aborts after ms milliseconds and rejects, letting callers move on.
async function _fetchTO(url,opts,ms){
  const ctrl=new AbortController();
  const timer=setTimeout(()=>ctrl.abort(), ms||15000);
  try{ return await fetch(url,Object.assign({},opts||{},{signal:ctrl.signal})); }
  finally{ clearTimeout(timer); }
}
// Incremental update: if we already have recent saved history, fetch only a
// SHORT recent window and merge the new days on — instead of re-pulling months.
// Falls back to a full fetch when there's nothing saved or the gap is large.
// ═══ v416 STAGE-2 FAST LOADS — whole DAYS from the pantry in one gulp ═══════
// Instead of 3,000+ per-share fetches, ask the server store which days it has
// that this device hasn't merged yet, pull each day ONCE (~4,300 bars a call),
// and slot the bars into every share's saved history. Shares brought fully up
// to date are stamped fresh, so the per-share download loop skips them all.
// Careful bits:
//  · a share whose saved history is older than the fetched window would be left
//    with a HOLE — those shares are skipped here and rescued by the normal
//    per-share incremental path instead.
//  · every step degrades silently: any server hiccup and the old path still runs.
async function _srvFirstFill(exch,depth,say){
  /* v578: build saved history for EVERY share straight from your server's
     pantry, newest day backwards. One request per trading day (~4,300 bars,
     about 100KB) instead of one request per SHARE through a free public relay.
     The pantry stores full open/high/low/close/volume, so seeding from it is
     lossless — the old "never seed from thin day-slices" guard predates that. */
  const out={days:0,seeded:0,topped:0,shares:0,stopped:false};
  try{
    if(typeof _serverData!=='function'||!_serverData()){ if(say)say('\u26a0 Your server store is not switched on.'); return out; }
    const D=Math.max(30,Math.min(760,+depth||300));
    const jf=async(u,ms)=>{ const c=new AbortController(); const t=setTimeout(function(){try{c.abort();}catch(e){}},ms||15000);
      try{ const r=await fetch(DATA_PROXY+u,{signal:c.signal}); if(!r.ok)return null; return await r.json(); } finally{ clearTimeout(t); } };
    const latest=await jf('/history/latest?exch='+encodeURIComponent(exch),10000).catch(function(){return null;});
    const latestD=(latest&&latest.ok&&latest.date)?String(latest.date).slice(0,10):null;
    if(!latestD){ if(say)say('\u26a0 Could not read your server store.'); return out; }
    /* v579: same trust-but-verify as the day-sync (v455). A believable pointer
       (no older than a long weekend) lets filled shares be stamped "saved
       today", so the per-share download pass skips them — that is the whole
       point of filling by day. A stale pointer still merges the real bars but
       never claims freshness, so the ordinary path fills the gap. The v455
       backstop in fetchHistoryUpdate re-checks the claim against the newest
       bar before honouring it. */
    const _today=new Date().toISOString().slice(0,10);
    const _ptrAge=Math.round((Date.now()-Date.parse(latestD+'T00:00:00Z'))/86400000);
    const _ptrOK=isFinite(_ptrAge)&&_ptrAge<=5;
    const _fillStamp=_ptrOK?_today:latestD;
    const per=new Map();
    const d=new Date(latestD+'T12:00:00Z');
    let misses=0;
    for(let i=0;i<Math.ceil(D*1.5)+20&&out.days<D;i++){
      if(window._fillAbort){ out.stopped=true; break; }
      const ds=d.toISOString().slice(0,10);
      const dow=d.getUTCDay();
      if(dow!==0&&dow!==6){
        const day=await jf('/history/day/'+ds+'?exch='+encodeURIComponent(exch),20000).catch(function(){return null;});
        if(day&&day.ok&&Array.isArray(day.rows)&&day.rows.length){
          misses=0; out.days++;
          for(const r of day.rows){
            const t=String(r.t||'').toUpperCase(); if(!t)continue;
            let a=per.get(t); if(!a){a=[];per.set(t,a);}
            a.push({dateStamp:ds,open:(r.o!=null?r.o:r.c),high:(r.h!=null?r.h:r.c),low:(r.l!=null?r.l:r.c),close:r.c,volume:r.v||0});
          }
          if(say&&out.days%10===0)say('\ud83e\uddca Pulled '+out.days+' of '+D+' days from your server store...');
        } else { misses++; if(misses>=8)break; }
      }
      d.setUTCDate(d.getUTCDate()-1);
    }
    if(!out.days){ if(say)say('\u26a0 Your server store returned no days.'); return out; }
    const ticks=[...per.keys()];
    out.shares=ticks.length;
    for(let i=0;i<ticks.length;i+=150){
      if(window._fillAbort){ out.stopped=true; break; }
      const slice=ticks.slice(i,i+150);
      await Promise.all(slice.map(async function(t){
        try{
          const rows=per.get(t).slice().sort(function(a,b){ return a.dateStamp<b.dateStamp?-1:a.dateStamp>b.dateStamp?1:0; });
          const stored=await histGet(exch,t);
          const have=(stored&&Array.isArray(stored.rows))?stored.rows.length:0;
          if(have>=rows.length){ out.topped++; return; }
          await histPut(exch,t,rows,_fillStamp);
          if(have)out.topped++; else out.seeded++;
        }catch(e){}
      }));
      if(say)say('\ud83d\udcbe Saving - '+Math.min(i+150,ticks.length)+' of '+ticks.length+' shares...');
    }
    try{ localStorage.setItem('asxScreener.srvDaySync.v1.'+exch,latestD); }catch(e){}
    if(say)say('\u2705 Filled '+out.days+' days for '+out.shares.toLocaleString()+' shares from your server - '+out.seeded.toLocaleString()+' new, '+out.topped.toLocaleString()+' updated. Reload to use it.');
    return out;
  }catch(e){ if(say)say('\u26a0 Fill stopped: '+(e&&e.message?e.message:'unknown')); return out; }
}
