// Save all current Top 20 shares into a watchlist (asks which / new name).
function saveTop10ToWatch(){
  const pairs=(window._top20Shown&&window._top20Shown.length)?window._top20Shown:(window._lastTop10||[]);
  if(!pairs.length){alert('Run Top 20 first.');return;}
  const dflt='Top 20 '+new Date().toLocaleDateString('en-AU');
  const name=prompt('Save these 10 shares to which watchlist?\n\nType a name (existing or new):',dflt);
  if(name===null||!name.trim())return;
  const nm=name.trim();
  if(!watchlists[nm])watchlists[nm]={};
  let added=0;
  pairs.forEach(({s})=>{ if(!watchlists[nm][s.ticker]){watchlists[nm][s.ticker]=JSON.parse(JSON.stringify(s));added++;} });
  activeWatch=nm;
  saveWatchlists();updateWatchBtn();
  closeModal();
  alert(`Saved ${added} share${added===1?'':'s'} to “${nm}”. Open it via the ★ watchlist button.`);
}

