// ── All Signals combined scan ────────────────────────────────────────────────
// One pass over every share, checking EVERYTHING: sharp-mover abnormality,
// the five unusual-activity patterns, volume surge, both streaks, accumulation
// and the /10 score. Shares are ranked by how many signals they trigger.
// Technical signals scan — ranks shares by a blend of the classic indicators.
// Requires history (runs the 3-month refresh first if not yet computed).
async function technicalScan(){
  _scanStart('📐 Technical Signals Scan');
  exitWatchView&&exitWatchView();
  if(!allData.length){alert('Load an exchange (or CSV) first.');return;}
  const needHist=!allData.some(s=>s.techCalced);
  if(needHist){
    const ls=document.getElementById('loadStatus');
    if(ls)ls.innerHTML='📐 Fetching price history for technical signals… (runs the 3-month refresh)';
    if(window._offlineMode){ await _computeSignalsFromSeries(); } else { await bulkVolume(); }
  }
  const have=allData.filter(s=>s.techCalced);
  if(!have.length){alert('Technical signals need price history — tap ⚡ Load, then the 3-month refresh.');return;}
  // v485 — the twelve weights moved to _selTechnical. The counts below run over
  // the returned list; they do not care about its order.
  filtered=_selTechnical(have);
  sortKey='techScore';sortDir=-1;
  render();_scanDone();
  const gc=have.filter(s=>s.cross==='golden').length, nh=have.filter(s=>s.nearHigh).length, ob=have.filter(s=>s.rsiState==='oversold').length;
  const st=document.getElementById('loadStatus');
  if(st)st.innerHTML=`📐 <strong style="color:#58a6ff">Technical signals</strong> on ${have.length} shares · ${gc} golden cross · ${nh} near 52-wk high · ${ob} oversold (RSI≤30). <span style="color:var(--dim)">Estimates from closing prices — not advice.</span>`;
  // v712 — the scan worked but reported into a popup-status the user had to hunt for.
  try{
    if(document.body.classList.contains('simple-mode')){ _planResultsModal('\ud83d\udcd0 Technical-ranked'); }
    else{ setTimeout(function(){ try{ closeOverlay();
      var b=document.getElementById('activeScanBanner');
      if(b){ b.innerHTML='<div style="margin:8px 0;padding:9px 12px;border:1.5px solid #58a6ff;border-radius:10px;background:var(--bg2);font-weight:600;font-size:13px;font-family:var(--sans);">\ud83d\udcd0 Technical-ranked \u00b7 <b>'+filtered.length.toLocaleString()+'</b> shares, strongest first <div style="font-weight:400;font-size:10.5px;color:var(--dim);margin-top:3px;">Ranked by chart signals \u2014 golden cross, near 52-wk high, above 200-day, oversold RSI, rising money-flow, gap up. A pattern search, not graded evidence: nothing here has a proven edge.</div> <button onclick="doReset()" style="float:right;padding:3px 9px;border-radius:7px;border:1px solid var(--border2);background:var(--bg3);color:var(--text);cursor:pointer;font-weight:600;font-size:11px;font-family:var(--sans);">\u2715 Clear</button></div>'; }
      var t=document.getElementById('tblwrap'); if(t&&t.scrollIntoView)t.scrollIntoView({behavior:'smooth',block:'start'});
    }catch(_){}} ,650); }
  }catch(_){}
}
// Per-share technical detail (opens from the 📐 link on a row)
// ── 🔬 DEEP DIVE — everything Insight Trading knows about a share, plus smart
//    per-ticker links to the authoritative FREE sources for the data we don't
//    hold (shareholders, directors, announcements). Honest by design: we show
//    what we compute and route to official sources for the rest. ──────────────
function _extLinks(ticker,exch){
  const t=ticker.toLowerCase(), T=ticker.toUpperCase();
  if(exch==='ASX'){
    return [
      {label:'📢 ASX announcements (official)', url:`https://www.asx.com.au/markets/company/${T}`, note:'Company news & price-sensitive filings'},
      {label:'📰 Market Index — news & data', url:`https://www.marketindex.com.au/asx/${t}`, note:'Announcements, shareholders, directors'},
      {label:'👥 Top shareholders & insiders', url:`https://www.google.com/search?q=ASX+${T}+top+shareholders+ownership+insider+transactions`, note:'Top holders & director moves — via search; the old registry subpage was retired'},
      {label:'🧑‍💼 Director trades (ASX announcements)', url:directorUrlFor(t,'ASX'), note:'Official Appendix 3Y filings — director buying & selling'},
      {label:'🧑‍💼 Director trades (Market Index)', url:directorAltUrlFor(t,'ASX'), note:'Alternative: per-share page with director section'},
      {label:'📄 Company profile', url:`https://www.marketindex.com.au/asx/${t}/company`, note:'Business overview & financials'},
    ];
  }
  // Non-ASX fallback — Yahoo Finance sections
  return [
    {label:'📰 News', url:`https://finance.yahoo.com/quote/${T}/news/`, note:'Recent news'},
    {label:'👥 Major holders', url:`https://finance.yahoo.com/quote/${T}/holders/`, note:'Institutional & insider holders'},
    {label:'🧑‍💼 Insider transactions', url:`https://finance.yahoo.com/quote/${T}/insider-transactions/`, note:'Insider buying & selling'},
    {label:'📄 Profile', url:`https://finance.yahoo.com/quote/${T}/profile/`, note:'Company profile & officers'},
  ];
}
// ── PRICE CHART (line) — a full popup chart window ────────────────────────
// Draws a clean SVG line chart of a share's price history, with MA20 & MA50,
// the 4-week range band shaded, and volume bars along the bottom. Timeframe
// buttons (1M/3M/6M/Max) redraw from the retained history — no re-fetch.
let _chartTicker=null, _chartTF=66;  // default ~3 months
// ═══ v220 CHART ENGINE — candles, touch, trades, accumulation, benchmark, log ═══
function showChart(ticker){
  _chartTicker=ticker; _chartTF=66;
  try{window._chartStyle=localStorage.getItem('asxScreener.chartStyle.v1')==='candle'?'candle':'line';}catch(e){window._chartStyle='line';}
  try{window._chartLog=localStorage.getItem('asxScreener.chartLog.v1')==='1';}catch(e){window._chartLog=false;}
  window._chartBench=false;
  showModal(_chartHtml(ticker),'📈 '+ticker+' price chart');
}
function setChartTF(n){ _chartTF=n; _chartRerender(); const tabs=document.querySelectorAll('.chart-tf[data-tf]'); tabs.forEach(t=>t.classList.toggle('on', parseInt(t.dataset.tf)===n)); }
function _chartRerender(){
  const box=document.getElementById('chartArea'); if(box)box.innerHTML=_chartSvg(_chartTicker,_chartTF);
  const st=document.getElementById('chartStyleBtn'); if(st)st.textContent=(window._chartStyle==='candle')?'📈 Line':'🕯 Candles';
  const lg=document.getElementById('chartLogBtn'); if(lg)lg.classList.toggle('on',!!window._chartLog);
  const bm=document.getElementById('chartBenchBtn'); if(bm)bm.classList.toggle('on',!!window._chartBench);
}
function _chartToggleStyle(){
  window._chartStyle=(window._chartStyle==='candle')?'line':'candle';
  try{localStorage.setItem('asxScreener.chartStyle.v1',window._chartStyle);}catch(e){}
  _chartRerender();
}
function _chartToggleLog(){
  window._chartLog=!window._chartLog;
  try{localStorage.setItem('asxScreener.chartLog.v1',window._chartLog?'1':'0');}catch(e){}
  _chartRerender();
}
function _chartToggleBench(){
  if(!window._chartBench){
    const bm=(allData||[]).find(x=>['A200','VAS','STW','IOZ'].includes(x.ticker)&&Array.isArray(x._history)&&x._history.length>5);
    if(!bm){alert('To compare against the market, load an index ETF first (VAS, A200, STW or IOZ) so its history is stored — e.g. search for it and open its chart once.');return;}
  }
  window._chartBench=!window._chartBench;
  _chartRerender();
}
function _chartHtml(ticker){
  const s=(allData||[]).find(x=>x.ticker===ticker);
  const name=s?s.name||'':'';
  const tfBtn=(lbl,n)=>`<button class="chart-tf ${n===_chartTF?'on':''}" data-tf="${n}" onclick="setChartTF(${n})" style="padding:4px 9px;border-radius:5px;border:1px solid var(--border2);background:var(--bg3);color:var(--muted);font-weight:600;font-size:10px;font-family:var(--sans);cursor:pointer;">${lbl}</button>`;
  const tgl=(id,lbl,on,fn)=>`<button id="${id}" class="chart-tf ${on?'on':''}" onclick="${fn}()" style="padding:4px 9px;border-radius:5px;border:1px solid var(--border2);background:var(--bg3);color:var(--muted);font-weight:600;font-size:10px;font-family:var(--sans);cursor:pointer;">${lbl}</button>`;
  const _px=s&&s.price>0?fmtP(s.price,s.currency||''):'';
  const _cp=s&&s.chgPct!=null?s.chgPct:null;
  const _cc=_cp>0?'var(--green)':_cp<0?'#ff6b6b':'var(--muted)';
  const _hdr=_px?`<div style="text-align:right;line-height:1.15;"><div style="font-weight:800;font-size:19px;font-family:var(--mono);color:var(--text);">${_px}</div>${_cp!=null?`<div style="font-weight:700;font-size:11px;font-family:var(--mono);color:${_cc};">${_cp>0?'▲ +':_cp<0?'▼ ':''}${_cp.toFixed(2)}% today</div>`:''}</div>`:'';
  return `<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;"><div><div style="font-weight:800;font-size:16px;font-family:var(--sans);color:var(--gold);">${ticker} <span style="font-weight:400;font-size:12px;color:var(--muted);">${name}</span></div>
    <div style="font-size:9px;color:var(--dim);margin:3px 0 8px;">Price history · end-of-day data · touch or hover the chart for any day's numbers · estimates, not advice.</div></div>${_hdr}</div>
    <div style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:8px;align-items:center;">
      ${tfBtn('1M',20)}${tfBtn('3M',66)}${tfBtn('6M',132)}${tfBtn('1Y',252)}${tfBtn('Max',9999)}
      <span style="flex:1;"></span>
      ${tgl('chartStyleBtn',(window._chartStyle==='candle'?'📈 Line':'🕯 Candles'),false,'_chartToggleStyle')}
      ${tgl('chartLogBtn','Log',!!window._chartLog,'_chartToggleLog')}
      ${tgl('chartBenchBtn','vs mkt',!!window._chartBench,'_chartToggleBench')}
    </div>
    <div id="chartArea">${_chartSvg(ticker,_chartTF)}</div>`;
}
function _chartSvg(ticker, tf){
  const s=(allData||[]).find(x=>x.ticker===ticker);
  if(!s||!s._history||!s._history.length) return '<div style="color:var(--dim);font-size:11px;padding:30px 0;text-align:center;">No price history stored for this share yet.<br>Run a scan or the technical refresh to load its history, then reopen the chart.</div>';
  let rows=_sortedCloses(s._history);
  if(tf<rows.length) rows=rows.slice(-tf);
  if(rows.length<2) return '<div style="color:var(--dim);font-size:11px;padding:30px;text-align:center;">Not enough history to chart this timeframe.</div>';
  const W=620, H=310, padL=50, padR=58, padT=26, padB=64, volH=40;
  const closes=rows.map(r=>r.c), vols=rows.map(r=>isFinite(r.v)?r.v:0);
  const opens=rows.map(r=>isFinite(r.o)?r.o:null);
  const his=rows.map(r=>isFinite(r.hi)&&r.hi>0?r.hi:r.c), los=rows.map(r=>isFinite(r.lo)&&r.lo>0?r.lo:r.c);
  const ohlcOK=opens.filter(o=>o!=null&&o>0).length >= rows.length*0.5;
  const candleWanted=(window._chartStyle==='candle');
  const candle=candleWanted;                 // v280: always honour the toggle
  const approxCandles=candleWanted&&!ohlcOK; // closes-only history → approximate bodies
  const candleNote=(candleWanted&&!ohlcOK)?`<div style="margin-top:6px;font-size:9px;color:var(--orange);border:1px solid rgba(255,165,0,.4);background:rgba(255,165,0,.07);border-radius:6px;padding:5px 8px;">🕯 <strong>Approximate candles</strong> — this share's stored history has closes only, so each body runs from the previous close to the close (no true opens or wicks yet). The app now saves full open/high/low as each new day arrives; 🔄 Refresh / redownload data restores them at full depth right away.</div>`:'';
  const sLo=candle?Math.min(...los):Math.min(...closes);
  const sHi=candle?Math.max(...his):Math.max(...closes);
  const padV=(sHi-sLo)*0.08||sHi*0.05;
  const useLog=!!window._chartLog&&sLo>0;
  let yLo=useLog?Math.max(sLo*0.97,1e-6):sLo-padV;
  let yHi=useLog?sHi*1.03:sHi+padV;
  const plotW=W-padL-padR, plotH=H-padT-padB;
  const X=i=>padL+(i/(rows.length-1))*plotW;
  const lgLo=useLog?Math.log(yLo):0, lgHi=useLog?Math.log(yHi):0;
  const Y=useLog?(v=>padT+plotH-((Math.log(Math.max(v,1e-9))-lgLo)/(lgHi-lgLo))*plotH)
                :(v=>padT+plotH-((v-yLo)/(yHi-yLo))*plotH);
  window._chartRows=rows;
  window._chartGeom={W,H,padL,plotW,padT,plotH,cur:(s.currency||''),ys:rows.map(r=>Y(r.c)),candle};
  // moving averages (always from closes)
  const ma=(n,i)=>{ if(i<n-1)return null; let sum=0; for(let k=i-n+1;k<=i;k++)sum+=closes[k]; return sum/n; };
  const linePath=(fn)=>{ let d='',started=false; for(let i=0;i<rows.length;i++){const v=fn(i); if(v==null){started=false;continue;} d+=(started?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1)+' '; started=true;} return d; };
  const ma20P=linePath(i=>ma(20,i));
  const ma50P=linePath(i=>ma(50,i));
  // price: line + area OR candles
  let priceLayer='';
  if(candle){
    const cw=Math.max(1.5,Math.min(9,plotW/rows.length*0.66));
    for(let i=0;i<rows.length;i++){
      const o=(opens[i]!=null&&opens[i]>0)?opens[i]:(i>0?closes[i-1]:closes[i]), c=closes[i];
      const up=c>=o, col=up?'#3fb950':'#f85149';
      const x=X(i);
      priceLayer+=`<line x1="${x.toFixed(1)}" y1="${Y(his[i]).toFixed(1)}" x2="${x.toFixed(1)}" y2="${Y(los[i]).toFixed(1)}" stroke="${col}" stroke-width="1" opacity="0.9"/>`;
      const yT=Y(Math.max(o,c)), yB=Y(Math.min(o,c));
      priceLayer+=`<rect x="${(x-cw/2).toFixed(1)}" y="${yT.toFixed(1)}" width="${cw.toFixed(1)}" height="${Math.max(0.8,yB-yT).toFixed(1)}" fill="${col}" fill-opacity="${up?'0.9':'1'}" rx="0.5"/>`;
    }
  }else{
    const priceP=linePath(i=>closes[i]);
    const areaP=priceP+`L ${X(rows.length-1).toFixed(1)} ${(padT+plotH).toFixed(1)} L ${X(0).toFixed(1)} ${(padT+plotH).toFixed(1)} Z`;
    priceLayer=`<path d="${areaP}" fill="url(#pxFill)" stroke="none"/><path d="${priceP}" fill="none" stroke="#FFD200" stroke-width="6" stroke-opacity="0.10" stroke-linejoin="round" stroke-linecap="round"/><path d="${priceP}" fill="none" stroke="var(--gold)" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/>`;
  }
  // 4-week range band — clamped to view, drawn over the RECENT ~4 weeks only
  let band='';
  if(s.rangeLow!=null&&s.rangeHigh!=null&&s.rangeHigh>yLo&&s.rangeLow<yHi){
    const yH=Math.max(padT,Y(Math.min(s.rangeHigh,yHi)));
    const yL=Math.min(padT+plotH,Y(Math.max(s.rangeLow,yLo)));
    const from=Math.max(0,rows.length-21);
    const bx=X(from), bw2=X(rows.length-1)-bx;
    if(yL-yH>1&&bw2>2) band=`<rect x="${bx.toFixed(1)}" y="${yH.toFixed(1)}" width="${bw2.toFixed(1)}" height="${(yL-yH).toFixed(1)}" fill="rgba(63,185,80,.08)" stroke="rgba(63,185,80,.30)" stroke-dasharray="3 3"/>`;
  }
  // y-axis gridlines — ROUND price steps (1-2-5), labelled on the RIGHT axis
  let grid='';
  {
    const gv=[];
    if(useLog){ for(let g=0;g<=4;g++) gv.push(Math.exp(lgLo+(lgHi-lgLo)*(g/4))); }
    else{
      const span=yHi-yLo, raw=span/4.5, mag=Math.pow(10,Math.floor(Math.log10(raw)));
      const norm=raw/mag, step=(norm<=1?1:norm<=2?2:norm<=5?5:10)*mag;
      for(let v=Math.ceil(yLo/step)*step; v<=yHi+1e-9; v+=step) gv.push(v);
      if(gv.length<2){ gv.length=0; for(let g=0;g<=4;g++) gv.push(yLo+(yHi-yLo)*(g/4)); }
    }
    for(const val of gv){
      const y=Y(val);
      if(y<padT-1||y>padT+plotH+1)continue;
      grid+=`<line x1="${padL}" y1="${y.toFixed(1)}" x2="${W-padR}" y2="${y.toFixed(1)}" stroke="var(--border)" stroke-width="1" opacity="0.45"/><text x="${W-padR+5}" y="${(y+3).toFixed(1)}" text-anchor="start" font-size="8.5" fill="var(--dim)" font-family="var(--mono)">${fmtP(val,s.currency||'')}</text>`;
    }
    grid+=`<line x1="${padL}" y1="${(padT+plotH).toFixed(1)}" x2="${W-padR}" y2="${(padT+plotH).toFixed(1)}" stroke="var(--border)" stroke-width="1" opacity="0.9"/>`;
  }
  // volume bars + rolling-average line
  const vHi=Math.max(...vols)||1; const vTop=H-padB+16;
  const avgAt=i=>{const n=Math.min(20,i); if(n<5)return null; let sum=0; for(let k=i-n;k<i;k++)sum+=vols[k]; return sum/n;};
  let volBars='';
  const bw=Math.max(1,plotW/rows.length*0.72);
  for(let i=0;i<rows.length;i++){ const h=Math.max(0.5,(vols[i]/vHi)*volH); const x=X(i)-bw/2; const up=i===0||closes[i]>=closes[i-1]; volBars+=`<rect x="${x.toFixed(1)}" y="${(vTop+volH-h).toFixed(1)}" width="${bw.toFixed(1)}" height="${h.toFixed(1)}" fill="${up?'rgba(63,185,80,.45)':'rgba(226,25,55,.45)'}" rx="0.5"/>`; }
  let volAvg=''; { let d='',started=false;
    for(let i=0;i<rows.length;i++){const av=avgAt(i); if(!av){started=false;continue;} const y=vTop+volH-Math.min(1,av/vHi)*volH; d+=(started?'L':'M')+X(i).toFixed(1)+' '+y.toFixed(1)+' '; started=true;}
    if(d)volAvg=`<path d="${d}" fill="none" stroke="#8fa6c9" stroke-width="1" stroke-dasharray="3 2" opacity="0.9"/>`;
  }
  // accumulation-day dots: up day on volume well above average above its rolling average
  let accDots='';
  for(let i=1;i<rows.length;i++){
    const av=avgAt(i);
    if(av&&vols[i]>=av*1.5&&closes[i]>closes[i-1]){
      const base=candle?Y(los[i]):Y(closes[i]);
      accDots+=`<circle cx="${X(i).toFixed(1)}" cy="${Math.min(base+7,padT+plotH-2).toFixed(1)}" r="2" fill="var(--gold)" stroke="#0d1b33" stroke-width="0.6"/>`;
    }
  }
  // benchmark overlay (indexed to the first visible close)
  let benchLine='',benchLbl='';
  if(window._chartBench){
    const bm=(allData||[]).find(x=>['A200','VAS','STW','IOZ'].includes(x.ticker)&&Array.isArray(x._history)&&x._history.length>5);
    if(bm){
      const br=_sortedCloses(bm._history); const map={}; br.forEach(r=>{map[r.d]=r.c;});
      const bdates=Object.keys(map).sort();
      const at=d=>{let best=null;for(const dd of bdates){if(dd<=d)best=dd;else break;}return best?map[best]:null;};
      const b0=at(rows[0].d);
      if(b0>0){
        let d='',started=false;
        for(let i=0;i<rows.length;i++){const bv=at(rows[i].d); if(!(bv>0)){started=false;continue;}
          const v=Math.max(yLo,Math.min(yHi,(bv/b0)*closes[0]));
          d+=(started?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1)+' '; started=true;}
        if(d){benchLine=`<path d="${d}" fill="none" stroke="#58a6ff" stroke-width="1.2" stroke-dasharray="4 3" opacity="0.9"/>`;benchLbl=bm.ticker;}
      }
    }
  }
  // your paper trades on this share: ▲ buys, ▼ sells, 🎯/🛑 lines
  let trades='',tradesShown=false;
  try{
    const p=_paper();
    const idxOf=dt=>{ if(!dt)return -1; const d=String(dt).slice(0,10); if(d>rows[rows.length-1].d)return -1; for(let i=0;i<rows.length;i++){ if(rows[i].d>=d)return i; } return -1; };
    const inY=v=>isFinite(v)&&v>=yLo&&v<=yHi;
    (p.holdings||[]).filter(h=>h.ticker===ticker&&(!s.exchange||!h.exchange||h.exchange===s.exchange)).forEach(h=>{
      const i=idxOf(h.buyDate);
      if(i>=0&&inY(h.buyPrice)){trades+=`<path d="M ${X(i).toFixed(1)} ${(Y(h.buyPrice)-1).toFixed(1)} l -4.5 7.5 h 9 Z" fill="#3fb950" stroke="#0d1b33" stroke-width="0.7"><title>Holding: bought ${h.qty} @ ${fmtP(h.buyPrice,s.currency||'')} on ${h.buyDate}</title></path>`;tradesShown=true;}
      if(h.target>0&&inY(h.target)){trades+=`<line x1="${padL}" y1="${Y(h.target).toFixed(1)}" x2="${W-padR}" y2="${Y(h.target).toFixed(1)}" stroke="var(--gold)" stroke-width="1" stroke-dasharray="5 3" opacity="0.7"/><text x="${W-padR-3}" y="${(Y(h.target)-3).toFixed(1)}" text-anchor="end" font-size="8" fill="var(--gold)" font-family="var(--mono)">🎯 ${fmtP(h.target,s.currency||'')}</text>`;}
      if(h.stop>0&&inY(h.stop)){trades+=`<line x1="${padL}" y1="${Y(h.stop).toFixed(1)}" x2="${W-padR}" y2="${Y(h.stop).toFixed(1)}" stroke="#ff6b6b" stroke-width="1" stroke-dasharray="5 3" opacity="0.7"/><text x="${W-padR-3}" y="${(Y(h.stop)+9).toFixed(1)}" text-anchor="end" font-size="8" fill="#ff6b6b" font-family="var(--mono)">🛑 ${fmtP(h.stop,s.currency||'')}</text>`;}
    });
    (p.history||[]).filter(t=>t.ticker===ticker).slice(0,12).forEach(t=>{
      const bi=idxOf(t.buyDate);
      if(bi>=0&&inY(t.buyPrice)){trades+=`<path d="M ${X(bi).toFixed(1)} ${(Y(t.buyPrice)-1).toFixed(1)} l -4 6.5 h 8 Z" fill="rgba(63,185,80,.55)" stroke="#0d1b33" stroke-width="0.6"><title>Bought ${t.qty} @ ${fmtP(t.buyPrice,s.currency||'')} on ${t.buyDate}</title></path>`;tradesShown=true;}
      const si=idxOf(t.sellDate);
      if(si>=0&&inY(t.sellPrice)){trades+=`<path d="M ${X(si).toFixed(1)} ${(Y(t.sellPrice)+1).toFixed(1)} l -4 -6.5 h 8 Z" fill="rgba(226,25,55,.8)" stroke="#0d1b33" stroke-width="0.6"><title>Sold ${t.qty} @ ${fmtP(t.sellPrice,s.currency||'')} on ${t.sellDate} · P/L ${t.plAbs>=0?'+':''}${t.plAbs}</title></path>`;tradesShown=true;}
    });
  }catch(e){}
  // high / low markers on the scale actually shown
  const hiArr=candle?his:closes, loArr=candle?los:closes;
  const hiV=Math.max(...hiArr), loV=Math.min(...loArr);
  const hiI=hiArr.indexOf(hiV), loI=loArr.indexOf(loV);
  const hiAnchor=hiI>rows.length*0.8?'end':hiI<rows.length*0.2?'start':'middle';
  const loAnchor=loI>rows.length*0.8?'end':loI<rows.length*0.2?'start':'middle';
  const marks=`<circle cx="${X(hiI).toFixed(1)}" cy="${Y(hiV).toFixed(1)}" r="2.4" fill="var(--green)"/><text x="${X(hiI).toFixed(1)}" y="${(Y(hiV)-6).toFixed(1)}" text-anchor="${hiAnchor}" font-size="8.5" fill="var(--green)" font-family="var(--mono)">▲ ${fmtP(hiV,s.currency||'')}</text>
    <circle cx="${X(loI).toFixed(1)}" cy="${Y(loV).toFixed(1)}" r="2.4" fill="#ff6b6b"/><text x="${X(loI).toFixed(1)}" y="${(Y(loV)+13).toFixed(1)}" text-anchor="${loAnchor}" font-size="8.5" fill="#ff6b6b" font-family="var(--mono)">▼ ${fmtP(loV,s.currency||'')}</text>`;
  // last price tag + period chip + x labels
  const lc=closes[closes.length-1], ly=Y(lc);
  const lastTag=`<line x1="${padL}" y1="${ly.toFixed(1)}" x2="${(W-padR).toFixed(1)}" y2="${ly.toFixed(1)}" stroke="var(--gold)" stroke-width="1" stroke-dasharray="1.5 3.5" opacity="0.35"/>
    <circle cx="${X(rows.length-1).toFixed(1)}" cy="${ly.toFixed(1)}" r="3" fill="var(--gold)" stroke="#0d1b33" stroke-width="1"/>
    <rect x="${(W-padR+4)}" y="${(ly-8).toFixed(1)}" width="${padR-8}" height="16" rx="4" fill="var(--gold)"/>
    <text x="${(W-padR+4+(padR-8)/2)}" y="${(ly+3.4).toFixed(1)}" text-anchor="middle" font-size="9" font-weight="700" fill="#0d1b33" font-family="var(--mono)">${fmtP(lc,s.currency||'')}</text>`;
  const pct=((lc/closes[0])-1)*100;
  const chipCol=pct>=0?'var(--green)':'#ff6b6b';
  const chip=`<text x="${padL+4}" y="${padT-9}" font-size="10" font-weight="700" fill="${chipCol}" font-family="var(--mono)">${pct>=0?'▲ +':'▼ '}${pct.toFixed(1)}% over this period${useLog?' · log scale':''}</text>`;
  const _MN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const _fd=d=>{const m=parseInt(d.slice(5,7),10)-1,dd=parseInt(d.slice(8,10),10);return dd+' '+_MN[m];};
  let xlabels='';
  if(rows.length>45){
    let lastM=rows[0].d.slice(0,7);
    for(let i=1;i<rows.length;i++){
      const ym=rows[i].d.slice(0,7);
      if(ym!==lastM){
        lastM=ym;
        const x=X(i);
        if(x>padL+16&&x<W-padR-16){
          const m=parseInt(ym.slice(5,7),10)-1;
          const lbl=(m===0)?_MN[m]+' '+ym.slice(2,4):_MN[m];
          xlabels+=`<line x1="${x.toFixed(1)}" y1="${(padT+plotH).toFixed(1)}" x2="${x.toFixed(1)}" y2="${(padT+plotH+4).toFixed(1)}" stroke="var(--border)" opacity="0.9"/><line x1="${x.toFixed(1)}" y1="${padT}" x2="${x.toFixed(1)}" y2="${(padT+plotH).toFixed(1)}" stroke="var(--border)" stroke-width="1" opacity="0.18"/><text x="${x.toFixed(1)}" y="${H-padB+11}" text-anchor="middle" font-size="8.5" fill="var(--dim)" font-family="var(--mono)">${lbl}</text>`;
        }
      }
    }
    xlabels+=`<text x="${X(0).toFixed(1)}" y="${H-padB+11}" text-anchor="start" font-size="8.5" fill="var(--dim)" font-family="var(--mono)">${_fd(rows[0].d)}</text>`;
  }else{
    [0,Math.floor(rows.length/3),Math.floor(rows.length*2/3),rows.length-1].forEach((i,k)=>{
      xlabels+=`<text x="${X(i).toFixed(1)}" y="${H-padB+11}" text-anchor="${k===0?'start':k===3?'end':'middle'}" font-size="8.5" fill="var(--dim)" font-family="var(--mono)">${_fd(rows[i].d)}</text>`;
    });
  }
  // legend (reflects current mode)
  const leg=(sw,txt)=>`<span style="display:inline-flex;align-items:center;gap:4px;white-space:nowrap;">${sw}<span>${txt}</span></span>`;
  const legend=`<div style="display:flex;gap:11px;flex-wrap:wrap;margin-top:8px;font-size:10px;color:var(--muted);">
    ${candle?leg('<span style="display:inline-block;width:7px;height:10px;background:#3fb950;border-radius:1px;"></span>','up day')+leg('<span style="display:inline-block;width:7px;height:10px;background:#f85149;border-radius:1px;"></span>','down day'):leg('<span style="display:inline-block;width:14px;height:3px;background:var(--gold);"></span>','Price')}
    ${leg('<span style="display:inline-block;width:14px;height:3px;background:#58a6ff;"></span>','MA20')}
    ${leg('<span style="display:inline-block;width:14px;height:3px;background:#c88bff;"></span>','MA50')}
    ${leg('<span style="display:inline-block;width:12px;height:9px;background:rgba(63,185,80,.15);border:1px solid rgba(63,185,80,.5);"></span>','4-wk range (recent)')}
    ${leg('<span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--gold);border:1px solid #0d1b33;"></span>','accumulation day')}
    ${leg('<span style="display:inline-block;width:14px;height:0;border-top:2px dashed #8fa6c9;"></span>','avg volume')}
    ${benchLbl?leg('<span style="display:inline-block;width:14px;height:0;border-top:2px dashed #58a6ff;"></span>',benchLbl+' (indexed)'):''}
    ${tradesShown?leg('<span style="font-size:9px;">▲▼</span>','your paper trades'):''}
  </div>`;
  return `<svg id="pxChart" viewBox="0 0 ${W} ${H}" onmousemove="_chartMove(event)" onmouseleave="_chartOut()" ontouchstart="_chartTouch(event)" ontouchmove="_chartTouch(event)" style="width:100%;height:auto;background:linear-gradient(180deg,#0a1526,#0d1b33);border:1px solid var(--border2);border-radius:10px;cursor:crosshair;touch-action:none;">
    <defs>
      <linearGradient id="pxFill" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="#FFD200" stop-opacity="0.22"/>
        <stop offset="100%" stop-color="#FFD200" stop-opacity="0"/>
      </linearGradient>
    </defs>
    ${grid}${band}${chip}
    ${benchLine}
    <path d="${ma50P}" fill="none" stroke="#c88bff" stroke-width="1.2" opacity="0.85" stroke-linejoin="round"/>
    <path d="${ma20P}" fill="none" stroke="#58a6ff" stroke-width="1.2" opacity="0.85" stroke-linejoin="round"/>
    ${priceLayer}
    ${accDots}${trades}${marks}${lastTag}
    <line x1="${padL}" y1="${vTop}" x2="${W-padR}" y2="${vTop}" stroke="var(--border)"/>
    <text x="${padL-6}" y="${vTop+volH}" text-anchor="end" font-size="8" fill="var(--dim)" font-family="var(--mono)">Vol</text>
    ${volBars}${volAvg}${xlabels}
    <g id="chCross" style="display:none;pointer-events:none;">
      <line id="chCrossL" x1="0" y1="${padT}" x2="0" y2="${(padT+plotH)}" stroke="rgba(255,210,0,.5)" stroke-width="1" stroke-dasharray="3 3"/>
      <circle id="chCrossD" r="3.2" fill="none" stroke="var(--gold)" stroke-width="1.6"/>
    </g>
  </svg>${candleNote}${legend}`;
}
// Crosshair: shared by mouse AND touch — snaps to the nearest day, floats a tooltip.
function _chartHover(svg, clientX){
  const g=window._chartGeom, rows=window._chartRows;
  if(!g||!rows||!rows.length||!svg)return;
  const r=svg.getBoundingClientRect();
  const vx=(clientX-r.left)/r.width*g.W;
  let i=Math.round((vx-g.padL)/g.plotW*(rows.length-1));
  i=Math.max(0,Math.min(rows.length-1,i));
  const x=g.padL+(i/(rows.length-1))*g.plotW;
  const y=g.ys[i];
  const cross=svg.querySelector('#chCross'); if(!cross)return;
  cross.style.display='block';
  const L=svg.querySelector('#chCrossL'); L.setAttribute('x1',x); L.setAttribute('x2',x);
  const D=svg.querySelector('#chCrossD'); D.setAttribute('cx',x); D.setAttribute('cy',y);
  const area=document.getElementById('chartArea'); if(!area)return;
  let tip=document.getElementById('chTip');
  if(!tip){ tip=document.createElement('div'); tip.id='chTip';
    tip.style.cssText='position:absolute;z-index:5;pointer-events:none;background:#0a1526;border:1px solid var(--gold);border-radius:7px;padding:6px 9px;font-weight:600;font-size:10px;font-family:var(--mono);color:var(--text);box-shadow:0 6px 18px rgba(0,0,0,.45);white-space:nowrap;';
    area.style.position='relative'; area.appendChild(tip); }
  const row=rows[i];
  const prev=i>0?rows[i-1].c:null;
  const chg=prev?((row.c-prev)/prev*100):0;
  const cCol=chg>0?'var(--green)':chg<0?'#ff6b6b':'var(--muted)';
  const mid=(g.candle&&isFinite(row.o)&&row.o>0&&isFinite(row.hi)&&isFinite(row.lo))?`O ${fmtP(row.o,g.cur)} · H ${fmtP(row.hi,g.cur)} · L ${fmtP(row.lo,g.cur)}<br>`:'';
  tip.innerHTML=`<span style="color:var(--dim)">${row.d}</span><br>${mid}Close <b style="color:var(--gold)">${fmtP(row.c,g.cur)}</b> <span style="color:${cCol}">${chg>0?'+':''}${chg.toFixed(2)}%</span><br><span style="color:var(--dim)">Vol</span> ${fmtV(row.v||0)}`;
  const px=(x/g.W)*r.width, onRight=px>r.width*0.6;
  tip.style.left=onRight?'':(px+12)+'px'; tip.style.right=onRight?(r.width-px+12)+'px':'';
  tip.style.top=Math.max(4,(y/g.H)*r.height-30)+'px';
  tip.style.display='block';
}
function _chartMove(evt){ _chartHover(evt.currentTarget, evt.clientX); }
function _chartTouch(evt){
  const t=(evt.touches&&evt.touches[0])||null; if(!t)return;
  if(evt.cancelable)evt.preventDefault();
  _chartHover(evt.currentTarget, t.clientX);
}
function _chartOut(){
  const tip=document.getElementById('chTip'); if(tip)tip.style.display='none';
  const svg=document.getElementById('pxChart'); const c=svg&&svg.querySelector('#chCross'); if(c)c.style.display='none';
}


// ═══ v704 — study tools: flashcards + mixed quiz (self-contained, offline) ═══
const FLASHCARDS=[
 {d:'Signals',q:'🥇 Vol record',a:'Today\u2019s volume beats the share\u2019s previous 250-day record by 5%+ (min 10k traded). Big money can\u2019t hide its size.'},
 {d:'Signals',q:'⤴ MA cross',a:'The 20-day average crosses ABOVE the 50-day today. A slow, sturdy trend-turn signal \u2014 late by design.'},
 {d:'Signals',q:'🚀 Breakout',a:'Close above the prior 250-day high on 1.5\u00d7+ volume. New ground, with conviction behind it.'},
 {d:'Signals',q:'\ud83d\udccf 52-week high',a:'Closing at a 52-week high. Feels \u201ctoo expensive\u201d \u2014 but the trap is the feeling, not the share: strength tends to persist, so it\u2019s a look-closer signal, not a stay-away sign.'},
 {d:'Signals',q:'✝️ Golden Cross',a:'The 50-day average crosses above the 200-day. The slowest signal in the app \u2014 confirmation, not prediction.'},
 {d:'Signals',q:'🌀 RSI Recovery',a:'RSI climbs back above 30 after being oversold \u2014 the bounce, not the fall.'},
 {d:'Signals',q:'🤏 Volatility Squeeze',a:'The trading range compresses to unusually tight \u2014 a coiled spring. Says a move is near, not which way.'},
 {d:'Signals',q:'🏁 RS Leader',a:'Beating the MARKET over the window, not just rising. Strength relative to everyone else.'},
 {d:'Signals',q:'📰 News + Volume',a:'A price-sensitive announcement PLUS heavy volume \u2014 the first signal built on confirmed facts, not inference.'},
 {d:'Signals',q:'A sequence like \u201cVol record \u2192 then MA cross\u201d',a:'The ORDER matters: an early-warning signal followed by a confirmation. Graded as its own line, because \u201cbig money arrived, then the trend turned\u201d is a different claim than either alone.'},
 {d:'Evidence',q:'SOLID tier',a:'The edge showed up consistently with a decent sample behind it \u2014 the strongest grade the app gives.'},
 {d:'Evidence',q:'PROMISING tier',a:'A positive edge, but the sample or consistency isn\u2019t there yet. Watch, don\u2019t worship.'},
 {d:'Evidence',q:'NOT PROVEN',a:'Tested honestly and no edge found \u2014 printed right on the screen. Most tools hide this. Ours leads with it.'},
 {d:'Evidence',q:'PROVEN \u00b7 TOO SMALL',a:'A real edge that brokerage would eat. Statistically real \u2260 worth your money \u2014 the app knows the difference.'},
 {d:'Evidence',q:'The audit page',a:'Answers \u201cdid grades PREDICT or just describe?\u201d \u2014 every badge is re-tested on the window AFTER it was earned, on data it had never seen.'},
 {d:'Evidence',q:'The Paula\u2013Ni\u00f1o Edge (PN Edge)',a:'Average EXTRA money per $100, in the outcome window, beyond the market, before costs. Fixed scale: <$0.50 too small \u00b7 $0.50\u2013$2 decent \u00b7 $2\u2013$3.50 strong \u00b7 above that, be suspicious.'},
 {d:'Evidence',q:'Windows',a:'The app\u2019s three kinds of time: the sighting, the outcome window it\u2019s judged on, and the NEXT window the audit checks. Never graded on the window it was judged on.'},
 {d:'Numbers',q:'Volume streak',a:'Consecutive days with volume above the share\u2019s recent 3-MONTH average \u2014 the same average shown on its card. Tap the row in the deep dive to see the exact working.'},
 {d:'Numbers',q:'Accumulation (10d)',a:'How many of the last 10 days closed UP on volume well above average. Quiet-buying pattern \u2014 but index funds look identical, so it\u2019s a flag, not proof.'},
 {d:'Numbers',q:'🎯 Watch Score /10',a:'Accumulation is the backbone and carries most of the score; price streak adds a little, volume streak a little less, today\u2019s move least of all \u2014 on purpose.'},
 {d:'Numbers',q:'Surge rating',a:'Volume vs this share\u2019s own average: Mild +60% \u00b7 Warm +150% \u00b7 Hot +300% \u00b7 Intense +500% \u00b7 Extreme +1000%. Green = price up. A big-volume FALL is heavy selling, not bullish.'},
 {d:'Practice',q:'Paper trading',a:'Practice money, real prices, real fees modelled. Your rules run nightly on the server even with your phone off. Nothing touches real money without your tap.'},
 {d:'Practice',q:'Why write a reason on every buy?',a:'The note follows the trade into history. In a month, sorting wins and losses BY REASON shows which of your ideas actually work.'},
 {d:'Practice',q:'What this app never does',a:'It never tells you what to buy. It measures honestly \u2014 including the failures \u2014 and you make the calls. Research tool, not advice.'}
];
let _fc={deck:'All',i:0,flip:false,order:[]};
function _fcCards(){ return FLASHCARDS.filter(function(c){return _fc.deck==='All'||c.d===_fc.deck;}); }
function _fcRender(){
  var cards=_fcCards(); if(!_fc.order.length||_fc.order.length!==cards.length){_fc.order=cards.map(function(_,k){return k;});}
  var c=cards[_fc.order[_fc.i]||0]; if(!c)return;
  var decks=['All','Signals','Evidence','Numbers','Practice'];
  var chips=decks.map(function(d){return '<button type="button" onclick="_fcDeck(\''+d+'\')" style="padding:5px 10px;border-radius:14px;border:1px solid '+(d===_fc.deck?'var(--gold)':'var(--border2)')+';background:var(--bg3);color:var(--text);font-weight:600;font-size:11px;font-family:var(--sans);cursor:pointer;">'+d+'</button>';}).join(' ');
  var face=_fc.flip? '<div style="font-weight:400;font-size:14px;line-height:1.55;font-family:var(--sans);color:var(--ink);">'+c.a+'</div>'
                   : '<div style="font-weight:700;font-size:20px;font-family:var(--sans);">'+c.q+'</div><div style="margin-top:10px;color:var(--muted);font-weight:400;font-size:12px;font-family:var(--sans);">tap card to reveal</div>';
  var html='<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px;">'+chips+'</div>'
    +'<div onclick="_fcFlip()" style="min-height:210px;display:flex;flex-direction:column;justify-content:center;padding:18px;border:1.5px solid var(--gold);border-radius:14px;background:var(--bg2);cursor:pointer;text-align:center;">'+face+'</div>'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px;">'
    +'<button type="button" onclick="_fcStep(-1)" style="padding:8px 14px;border-radius:9px;border:1px solid var(--border2);background:var(--bg3);color:var(--text);cursor:pointer;font-weight:700;font-size:12px;font-family:var(--sans);">\u2039 Prev</button>'
    +'<span style="font-weight:600;font-size:12px;font-family:var(--sans);color:var(--muted);">'+(_fc.i+1)+' / '+cards.length+'</span>'
    +'<button type="button" onclick="_fcShuffle()" style="padding:8px 12px;border-radius:9px;border:1px solid var(--border2);background:var(--bg3);color:var(--text);cursor:pointer;font-weight:700;font-size:12px;font-family:var(--sans);">\ud83d\udd00</button>'
    +'<button type="button" onclick="_fcStep(1)" style="padding:8px 14px;border-radius:9px;border:1px solid var(--gold);background:var(--bg3);color:var(--text);cursor:pointer;font-weight:700;font-size:12px;font-family:var(--sans);">Next \u203a</button></div>';
  var box=document.getElementById('fcBox'); if(box)box.innerHTML=html;
}
function openFlashcards(){ _fc={deck:'All',i:0,flip:false,order:[]};
  showModal('<div style="font-weight:700;font-size:15px;font-family:var(--sans);margin-bottom:8px;">\ud83c\udccf Flashcards</div><div id="fcBox"></div>','Flashcards'); _fcRender(); }
function _fcDeck(d){ _fc.deck=d; _fc.i=0; _fc.flip=false; _fc.order=[]; _fcRender(); }
function _fcFlip(){ _fc.flip=!_fc.flip; _fcRender(); }
function _fcStep(n){ var N=_fcCards().length; _fc.i=(_fc.i+n+N)%N; _fc.flip=false; _fcRender(); }
function _fcShuffle(){ var o=_fc.order; for(var k=o.length-1;k>0;k--){var r=Math.floor(Math.random()*(k+1));var t=o[k];o[k]=o[r];o[r]=t;} _fc.i=0; _fc.flip=false; _fcRender(); }

