  // the background fresh-price load, a wake, the watchdog - and each restart
  // threw away minutes of work on a full market. Identical data joins or
  // skips; genuinely new data (fresh prices) still re-runs.
  try{
    var _psig=(currentExch||'')+'|'+allData.length+'|'+((allData[0]&&allData[0].code)||'')+'|'+((allData[0]&&allData[0].price)||'')+'|'+((allData[allData.length-1]&&allData[allData.length-1].code)||'');
    if(window._prepRunning && window._prepSig===_psig) return;
    if(!window._forceLiveRefresh && window._prepDoneSig===_psig) return;
    window._prepSig=_psig;
  }catch(_){}
  // We can prepare signals from EITHER a live API key OR the offline cache. Only
  // bail if we have neither (nothing to fetch history with).
