  try{haveOffline=(await histCount())>0;}catch(e){}
  if(!apiKey && !_serverData() && !haveOffline)return;
  try{
    const _offN=haveOffline?await histCount():0; window._savedN=_offN;
    if(!window._forceLiveRefresh && (window._offlineMode || _offN>=Math.min(allData.length,300))){
      window._preferOffline=true;
    } else { window._preferOffline=false; }
  }catch(e){ window._preferOffline=false; }
  if(window._prepRunning){
    // v243: never bail silently — say so, and auto-run when the current run
    // releases (load buttons pressed during a run used to just "do nothing").
    window._prepQueued=true;
    try{const _lsq=document.getElementById('loadStatus');if(_lsq)_lsq.innerHTML='<span style="color:var(--gold)">⏳ Another signal run is finishing — your request will start automatically right after.</span>';}catch(e){}
    return;
  }
  if(auto===true && window._prepFreshUntil && Date.now()<window._prepFreshUntil){window._prepFreshUntil=0;return;} // v234: just prepared from saved data — skip the duplicate auto-run
