// ── Sidebar: drag-to-resize + hide/show (persist) ───────────────────────────
const SIDEBAR_W_KEY='asxScreener.sidebarW', SIDEBAR_HIDDEN_KEY='asxScreener.sidebarHidden';
let _resizing=false;
function startResize(e){
  _resizing=true;document.body.classList.add('resizing');
  const move=ev=>{
    if(!_resizing)return;
    const left=document.querySelector('.left');
    const wrapLeft=document.querySelector('.wrap').getBoundingClientRect().left;
    let w=ev.clientX-wrapLeft;
    w=Math.max(260,Math.min(760,w));
    left.style.width=w+'px';
  };
  const up=()=>{
    _resizing=false;document.body.classList.remove('resizing');
    const left=document.querySelector('.left');
    try{localStorage.setItem(SIDEBAR_W_KEY,parseInt(left.style.width));}catch(_){}
    window.removeEventListener('mousemove',move);window.removeEventListener('mouseup',up);
  };
  window.addEventListener('mousemove',move);window.addEventListener('mouseup',up);
  e.preventDefault();
}
function resetSidebarWidth(){
  const left=document.querySelector('.left');left.style.width='380px';
  try{localStorage.setItem(SIDEBAR_W_KEY,380);}catch(_){}
}
function toggleSidebar(){
  const left=document.querySelector('.left');
  const handle=document.getElementById('resizeHandle');
  const btn=document.getElementById('sidebarToggle');
  const hidden=left.classList.toggle('hidden');
  if(handle)handle.classList.toggle('hidden',hidden);
  if(btn)btn.innerHTML=hidden?'▶ Show panel':'◀ Hide panel';
  try{localStorage.setItem(SIDEBAR_HIDDEN_KEY,hidden?'1':'0');}catch(_){}
}
