// ── "What changed since last time" ──────────────────────────────────────────
// Snapshots key per-share metrics each visit; on the next visit, surfaces the
// shares that crossed a meaningful threshold (newly accumulating, newly surging,
// big move). Uses the growing offline history — personal, proactive, offline.
const WHATSNEW_KEY='asxScreener.whatsNew.v1';
function _snapshotNow(){
  const snap={}; 
  if(!Array.isArray(allData))return snap;
  for(const s of allData){
    if(!s||!s.ticker)continue;
    snap[s.exchange+':'+s.ticker]={
      a:(s.accum10!=null?s.accum10:0),
      v:(s.volPct!=null&&isFinite(s.volPct)?s.volPct:0),
      w:(s.watchScore!=null?s.watchScore:0)
    };
  }
  return snap;
}
function _loadPrevSnapshot(){
  try{ const raw=localStorage.getItem(WHATSNEW_KEY); if(raw)return JSON.parse(raw); }catch(_){}
  return null;
}
function _savePrevSnapshot(snap,exch){
  try{ localStorage.setItem(WHATSNEW_KEY, JSON.stringify({when:new Date().toISOString(),exch:exch||currentExch||'',data:snap})); }catch(_){}
}
// Build the "what's new" items by comparing now vs the saved snapshot. Focuses on
// the user's WATCHLIST shares first (most relevant), then market-wide standouts.
function computeWhatsNew(){
  const prevWrap=_loadPrevSnapshot();
  const now=_snapshotNow();
  const items=[];
  // which shares does the user follow?
  let watched={};
  try{ watched=curWL()||{}; }catch(_){}
  const watchKeys=new Set(Object.values(watched).map(s=>s.exchange+':'+s.ticker));
  if(prevWrap&&prevWrap.data){
    const prev=prevWrap.data;
    for(const s of allData){
      if(!s||!s.ticker)continue;
      const key=s.exchange+':'+s.ticker;
      const p=prev[key]; if(!p)continue; // unseen last time
      const onWatch=watchKeys.has(key);
      // newly accumulating: crossed into 5+ accumulation days
      if((s.accum10||0)>=5 && (p.a||0)<5){
        items.push({sev:onWatch?3:1, ticker:s.ticker, exch:s.exchange, why:`started accumulating (${s.accum10}/10 days)`, onWatch});
      }
      // newly surging on volume: crossed +100% vol having been calm before
      else if((s.volPct||0)>=100 && (p.v||0)<50){
        items.push({sev:onWatch?3:1, ticker:s.ticker, exch:s.exchange, why:`volume jumped (+${s.volPct}%)`, onWatch});
      }
      // score climbed a lot
      else if((s.watchScore||0)>=6 && (s.watchScore||0)-(p.w||0)>=2){
        items.push({sev:onWatch?2:1, ticker:s.ticker, exch:s.exchange, why:`score rose to ${s.watchScore}/10`, onWatch});
      }
    }
  }
  // save this visit's snapshot for next time
  _savePrevSnapshot(now, currentExch);
  // sort: watchlist + strongest first, cap the list
  items.sort((a,b)=>b.sev-a.sev);
  return {items:items.slice(0,8), firstRun:!(prevWrap&&prevWrap.data)};
}
function renderWhatsNew(){
  const cards=[document.getElementById('whatsNewCard'),document.getElementById('whatsNewCardAdv')].filter(Boolean);
  if(!cards.length)return;
  if(!Array.isArray(allData)||!allData.length){ cards.forEach(c=>c.style.display='none'); return; }
  const {items,firstRun}=computeWhatsNew();
  if(firstRun||!items.length){ cards.forEach(c=>c.style.display='none'); return; }
  const _wnRow=it=>{
    const star=it.onWatch?'⭐ ':'';
    const col=it.onWatch?'var(--gold)':'var(--text)';
    const why=String(it.why||'').replace(/\(([^)]*)\)/g,m=>m.replace(/ /g,'\u00a0'));
    const s=(allData||[]).find(x=>x.ticker===it.ticker);
    const info=(s&&s.price>0)?`${fmtP(s.price,s.currency)} · <span style="color:${s.chgPct>=0?'var(--green)':'var(--red)'}">${s.chgPct>=0?'+':''}${(s.chgPct||0).toFixed(2)}% today</span>${(s.volCalced&&isFinite(s.volPct))?` · vol ${s.volPct>=0?'+':''}${Math.round(s.volPct)}%`:''}`:'';
    const inR=(typeof inResearch==='function')&&inResearch(it.ticker);
    const b=(fn,label,color)=>`<button onclick="event.stopPropagation();${fn}" style="width:100%;padding:9px 4px;border-radius:7px;border:1px solid ${color};background:color-mix(in srgb,${color} 10%,transparent);color:${color};font-weight:600;font-size:11px;font-family:var(--sans);cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${label}</button>`;
    return `<div style="border-top:1px solid var(--border);">
      <div onclick="_wnToggle(this)" style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:7px 2px;cursor:pointer;">
        <a href="#" onclick="event.stopPropagation();printShareReport('${it.ticker}');return false;" style="color:${col};font-weight:700;font-size:13px;text-decoration:none;white-space:nowrap;flex-shrink:0;">${star}${it.ticker}</a>
        <span style="font-size:11px;color:var(--muted);text-align:right;line-height:1.35;">${why} <span style="color:var(--dim);font-size:9px;">▾</span></span>
      </div>
      <div style="display:none;padding:2px 2px 9px;">
        ${info?`<div style="font-size:10px;color:var(--muted);font-family:var(--mono);margin-bottom:6px;">${info}</div>`:''}
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;">
          ${b(`printShareReport('${it.ticker}')`,'🖨 Report','var(--blue)')}
          ${b(`_wnWatch('${it.ticker}')`,it.onWatch?'★ Un-watch':'⭐ Watchlist','var(--gold)')}
          ${b(`paperBuy('${it.ticker}')`,'💼 Buy','var(--green)')}
          ${b(`_wnResearch('${it.ticker}')`,inR?'✓ Researching':'🔬 Research','#bc8cff')}
        </div>
      </div>
    </div>`;
  };
  const WN_SHOW=5;
  const rows=items.slice(0,WN_SHOW).map(_wnRow).join('')
    +(items.length>WN_SHOW?`<div style="display:none;">${items.slice(WN_SHOW).map(_wnRow).join('')}</div><a href="#" onclick="(function(a){const m=a.previousElementSibling;const open=m.style.display==='none';m.style.display=open?'':'none';a.textContent=open?'▲ Show fewer':'▼ Show all ${items.length}';})(this);return false;" style="display:block;text-align:center;font-size:11px;color:var(--blue);padding:8px 0 2px;text-decoration:none;border-top:1px solid var(--border);margin-top:4px;">▼ Show all ${items.length}</a>`:'');
  const html=`<div style="border:2px solid rgba(255,210,0,.75);border-radius:14px;padding:12px 14px;margin-bottom:12px;background:var(--bg2);box-shadow:0 0 14px rgba(255,210,0,.08);">
    <div style="font-weight:800;font-size:15px;color:var(--gold);margin-bottom:2px;">🔔 What's changed since last time</div>
    <div style="font-size:10.5px;color:var(--muted);margin-bottom:6px;">Shares that started moving since your last visit. ⭐ = on your watchlist. Tap a row for quick actions · tap the code to open its report. A data summary, not advice.</div>
    ${rows}
  </div>`;
  cards.forEach(c=>{ c.style.display='block'; c.innerHTML=html; });
}
// ── What's-changed row actions (v216) ────────────────────────────────────────
// Tap a row to reveal quick actions; tap the ticker itself to jump straight to
// its report. Only one action bar stays open per card.
function _wnToggle(rowEl){
  const act=rowEl.nextElementSibling;
  if(!act)return;
  const open=act.style.display==='none';
  try{
    const card=rowEl.closest('#whatsNewCard,#whatsNewCardAdv');
    if(card)card.querySelectorAll('.wn-open').forEach(x=>{if(x!==act){x.style.display='none';x.classList.remove('wn-open');}});
  }catch(_){}
  act.style.display=open?'block':'none';
  act.classList.toggle('wn-open',open);
}
function _wnWatch(t){
  try{toggleStar(t);}catch(_){}
  try{renderWhatsNew();}catch(_){}
}
function _wnResearch(t){
  try{toggleResearch(t);}catch(_){}
  try{renderWhatsNew();}catch(_){}
}
