    const today2=(window._exchDataDate&&window._exchDataDate[currentExch])||'';
    const buys=[]
      .concat((p.orders||[]).slice(-2).map(o=>'<div class="tc-trade">Buying <b style="color:var(--text)">'+esc(o.ticker)+'</b> at $'+(+o.limit).toFixed(+o.limit<1?3:2)+whyOf(o.note)+' <span class="dim">(waiting for its price)</span></div>'))
