// ═══ v487 — THE SHADOW CHECK ══════════════════════════════════════════════
// Ask the server to run the same ten reports over the same shares, and compare
// its answer with ours, position by position. Nothing on screen changes: this
// exists to earn the right to delete our own copy later, and a comparison run
// on invented data cannot earn it.
const _REP_OPEN=['allSignals','unusual','volumeSurge','topTen','gaps','smart','pullback','recovery','quietMovers','sharpMovers'];
const _REP_NAME={allSignals:'📋 All Signals',unusual:'🔥 Unusual Activity',volumeSurge:'📊 Volume Surge',
  topTen:'🏆 Top 20',gaps:'🕳 Gap Report',smart:'🎯 Smart Money',pullback:'🪜 Pullback',
  recovery:'↩️ Recovery Watch',quietMovers:'🫧 Quiet Movers',sharpMovers:'🚨 Sharp Movers'};

// An even spread across the loaded list, not the first N. The first 300 by
// ticker are the A's, which on the ASX is mostly tiny miners — a sample that
// would miss every large, liquid share the floors are there to separate.
function _repSample(n){
  var pool=[],i;
  for(i=0;i<allData.length;i++){
    var s=allData[i];
    if(s&&Array.isArray(s.series)&&s.series.length>=30&&s.price>0)pool.push(s);
  }
  if(pool.length<=n)return pool;
  var step=pool.length/n,out=[];
  for(var k=0;k<n;k++)out.push(pool[Math.floor(k*step)]);
  return out;
}

// Our own ten, over exactly the array we are about to upload.
async function _repLocal(sample){
  var out={},k;
  var FN={allSignals:_selAllSignals,unusual:_selUnusual,volumeSurge:_selVolumeSurge,
    topTen:_selTopTen,gaps:_selGaps,smart:_selSmartCandidates,pullback:_selPullback,
    recovery:_selRecovery,quietMovers:_selQuietMovers,sharpMovers:_selSharpMovers};
  for(var i=0;i<_REP_OPEN.length;i++){
    k=_REP_OPEN[i];
    var args=(k==='sharpMovers')?[speedSensitivity]:(k==='smart')?[3,false]:[];
    var r=null;
    try{
      r=FN[k].apply(null,[sample.slice()].concat(args));
      if(r&&typeof r.then==='function')r=await r;
    }catch(e){ r=null; }
    var list=Array.isArray(r)?r:((r&&(r.rows||r.candidates))||[]);
    out[k]={tickers:list.map(function(x){return (x&&x.s&&x.s.ticker)?x.s.ticker:(x&&x.ticker)?x.ticker:String(x);}),
            noOpen:(r&&r.noOpen!=null)?r.noOpen:null};
  }
  return out;
}

async function serverReportCheck(){
  var el=document.getElementById('srvChkOut');
  var say=function(h){ if(el)el.innerHTML=h; };
  if(!Array.isArray(allData)||allData.length<50){ say('Load a market first — there is nothing to compare.'); return; }
  if(!DATA_PROXY){ say('No server address configured.'); return; }
  var sample=_repSample(300);
  if(sample.length<50){ say('Only '+sample.length+' shares have enough history to compare. Load saved data or run a full load first.'); return; }
  say('Comparing '+sample.length+' shares…');
  // v507 — measure the sample's history depth HERE, on the exact shares being
  // compared, so a 🪜 Pullback gap arrives with its own explanation. Both sides
  // run the identical rule (verified clause-by-clause, 29 July); the rule's
  // lenient branch passes a share on the 50-day test alone when no 200-day
  // average exists. The server's pantry is deep, so the strict branch applies
  // to nearly everything there; shallow downloads here take the lenient branch.
  // More history = stricter test — which is the whole 42-vs-23 mechanism.
  var _dep={have200:0,noView:0};
  try{
    for(var _di=0;_di<sample.length;_di++){
      var _ds=sample[_di], _ser=_ds.series||[];
      var _n=0; for(var _dj=0;_dj<_ser.length;_dj++){ var _dc=_ser[_dj]&&(_ser[_dj].c!=null?_ser[_dj].c:_ser[_dj].close); if(_dc>0)_n++; }
      if(_n>=200){ _dep.have200++; continue; }
      // v508: 🪜 is strict on both sides now — nothing passes leniently. What
      // still matters is how many shares this device simply CANNOT judge.
      _dep.noView++;
    }
  }catch(e){}
  var mine;
  try{ mine=await _repLocal(sample); }catch(e){ say('This device could not run the reports: '+e); return; }
  var dd=(window._exchDataDate&&window._exchDataDate[currentExch])||'';
  var body={exch:currentExch,dataDate:dd,cap:((typeof F!=='undefined'&&F&&F.cap)||'any'),
    sensitivity:speedSensitivity,minDays:3,scanAll:false,
    shares:sample.map(function(s){return {ticker:s.ticker,series:s.series};})};
  var j=null;
  try{
    var r=await _fetchTO(DATA_PROXY.replace(/\/+$/,'')+'/reports',
      {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)},30000);
    if(r.status===404||r.status===405){ say('This server does not have the reports yet (it needs w395 or later).'); return; }
    if(!r.ok){ say('The server answered '+r.status+'.'); return; }
    j=await r.json();
  }catch(e){ say('Could not reach the server: '+e); return; }
  if(!j||!j.ok||!j.picks){ say('The server did not send an answer it could stand behind.'); return; }

  var rows=[],agree=0;
  for(var i=0;i<_REP_OPEN.length;i++){
    var k=_REP_OPEN[i], a=(mine[k]&&mine[k].tickers)||[], b=(j.picks[k]&&j.picks[k].tickers)||[];
    var why='';
    if(a.length!==b.length)why='this device '+a.length+', server '+b.length;
    else{
      for(var p=0;p<a.length;p++){ if(a[p]!==b[p]){ why='differs at position '+(p+1)+': '+a[p]+' here, '+b[p]+' there'; break; } }
    }
    // The one honest exception: without today's opening prices this device
    // cannot find a gap at all, and the server can. Say which, rather than
    // calling the server wrong.
    if(why&&k==='gaps'){
      var mo=mine[k].noOpen, so=(j.picks[k].extras&&j.picks[k].extras.noOpen);
      if(mo!=null&&so!=null&&mo!==so)
        why+=' — this device had no opening price for '+mo+' shares, the server for '+so;
    }
    if(!why)agree++;
    rows.push('<div style="margin:2px 0">'+(why?'<span style="color:#ff9caa">✗</span> ':'<span style="color:var(--green)">✓</span> ')+
      _REP_NAME[k]+' <span style="color:var(--dim)">('+a.length+')</span>'+(why?'<br><span style="color:var(--dim);padding-left:14px">'+why+'</span>':'')+'</div>');
  }
  var head=(agree===_REP_OPEN.length)
    ? '<b style="color:var(--green)">All '+agree+' reports agree</b> — same shares, same order, on '+sample.length+' of your real ones.'
    : '<b style="color:var(--gold)">'+agree+' of '+_REP_OPEN.length+' agree</b> on '+sample.length+' real shares.';
  var _depLine='<div style="margin-top:5px;font-size:9px;color:var(--dim);line-height:1.5;">'
    +'📏 depth here: <b>'+_dep.have200+'</b> of '+sample.length+' have 200+ days on this device'
    +(_dep.noView?' · 🪜 needs a 200-day view and <b>'+_dep.noView+'</b> don\'t have one here yet — this device cannot judge them, so the server, which holds the full year, may rightly find pullbacks this device cannot see':'')
    +'</div>';
  say(head+_depLine+'<div style="margin-top:6px">'+rows.join('')+'</div>'+
      '<div style="color:var(--dim);margin-top:5px">Server had opening prices for '+(j.bars||0)+
      ' shares and graded '+(j.graded||0)+'. Nothing on screen changed — this is only a comparison.</div>');
}
// ═══ v282 — shared liquidity-floor test (💧 Type tab) ═══
function _liqPass(s){
  if(typeof F==='undefined'||!F||!F.cap||F.cap==='any')return true;
  const liq=((s.avgVol>0?s.avgVol:(s.volume||0))*(s.price||0));
  const need=F.cap==='l50'?50e3:F.cap==='l250'?250e3:F.cap==='l1m'?1e6:0;
  return liq>=need;
}
// ═══ v282 — 🕳 Gap Report: opened away from yesterday — held vs faded ═══
async function gapScan(){
  _scanStart('🕳 Gap Report');
  exitWatchView&&exitWatchView();
  _resetBeforeScan();
  const st=document.getElementById('smartStatus');
  if(!allData||!allData.length){ if(st)st.textContent='Load your shares first, then run the Gap Report.'; _scanDone&&_scanDone(); return; }
  if(_freshenSeriesFromBulk)await _freshenSeriesFromBulk();
  if(!allData.some(s=>s.volCalced&&Array.isArray(s.series))){
    const hasKey=(()=>{try{return !!(document.getElementById('apiKey')&&document.getElementById('apiKey').value.trim())||!!localStorage.getItem('asxScreener.apiKey');}catch(_){return false;}})();
    if(window._offlineMode||!hasKey){if(_computeSignalsFromSeries)await _computeSignalsFromSeries();}
    else{ if(st)st.textContent='Loading price history…'; if(typeof bulkVolume==='function')await bulkVolume(); }
  }
  // v485 — the deciding moved to _selGaps. The six bucket counts below are
  // derived from these rows, so they did not have to move with it.
  const _gp=_selGaps(allData.filter(function(x){return x&&x.type!=='Option'&&x.type!=='Preference'&&x.type!=='Bond';})) /* v766: warrants (BHPMOS, ALDSO1…) were topping the gap lists — the wrapper filters so the parity-mirrored _selGaps stays byte-identical to the worker's */;
  const rows=_gp.rows; const priced=_gp.priced, noOpen=_gp.noOpen;
  F.dir='all';F.daysMin=0;F.days='0';F.volLo=0;F.volHi=Infinity;F.minScore=0;
  filtered=rows.map(x=>x.s);
  lastScanLabel='Gap Report';
  _resetStatsForNewView();
  document.getElementById('sortSel').value='chgPct';sortKey='chgPct';sortDir=-1;
  render();statsBar();dots&&dots();mkBadges&&mkBadges();_scanDone&&_scanDone();
  document.getElementById('statsBar').style.display='';
  document.getElementById('toolbar').style.display='flex';
  if(typeof scanProgSet==='function')scanProgSet(100);
  if(typeof scanProgHide==='function')scanProgHide();
  const B=k=>rows.filter(x=>x.s._gapBucket===k);
  const held=B('heldUp'),part=B('partUp'),fade=B('fadedUp'),rec=B('downRec'),dpart=B('downPart'),weak=B('downWeak');
  const ups=held.length+part.length+fade.length, downs=rec.length+dpart.length+weak.length;
  if(st){
    if(rows.length){
      st.innerHTML=`🕳 <strong style="color:var(--amber)">${rows.length}</strong> gapped 3%+ at the open — ⬆ ${ups} up (${held.length} held · ${fade.length} faded) · ⬇ ${downs} down (${rec.length} recovered)`+
        `<br><span style="font-size:9px;color:var(--orange)">Gap = today's OPEN vs yesterday's close. The panel groups held vs faded; the table is sorted by day change. Estimate — not advice.</span>`;
    }else{
      st.innerHTML=(noOpen>=Math.max(1,priced)*0.7)
        ? 'No stored opens for most shares yet — the app saves each day\'s open from now on (part of the candles fix). 🔄 Refresh / redownload data fills them in immediately.'
        : 'No 3%+ opening gaps in today\'s data.';
    }
  }
  if(rows.length){
    const row=x=>{const s=x.s;const up=s._gapPct>0;return `<div onclick="try{closeModal();}catch(e){};deepDive('${s.ticker}')" style="display:flex;gap:8px;align-items:flex-start;padding:5px 6px;border-bottom:1px solid var(--border2);cursor:pointer;border-radius:6px;" onmouseover="this.style.background='rgba(255,255,255,.03)'" onmouseout="this.style.background='transparent'"><span style="font-size:13px;flex:none;">${up?'⬆':'⬇'}</span><span style="font-size:11.5px;color:var(--muted);line-height:1.45;"><b style="color:var(--gold)">${s.ticker}</b>${(typeof _laChip==='function'&&_laChip(s))||''} opened ${s._gapPct>0?'+':''}${s._gapPct}% ${up?'above':'below'} yesterday's close and ${s._gapKept>100?`kept the WHOLE gap and closed above its open`:`kept ${s._gapKept}% of the gap by the close`}${(s.volCalced&&s.volPct>=100)?` on +${Math.round(s.volPct)}% volume`:''}.</span></div>`;};
    const sec=(t,arr)=>arr.length?`<div style="font-weight:700;font-size:11px;font-family:var(--sans);color:var(--text);margin:9px 0 2px;">${t} <span style="font-weight:400;color:var(--dim);">· ${arr.length}</span></div>${arr.slice(0,8).map(row).join('')}${arr.length>8?`<div style="font-size:9px;color:var(--dim);padding:3px 6px;">…all ${arr.length} are in the table underneath.</div>`:''}`:'';
    const head=`<div style="font-weight:700;font-size:15px;color:var(--text);">🕳 Gap Report</div><div style="font-size:9.5px;color:var(--dim);margin:3px 0 8px;">Shares that OPENED 3%+ away from yesterday's close — overnight news or a rush of morning orders. What matters is whether the gap survived the day. <span style="color:var(--dim)">Options, notes &amp; prefs excluded.</span><div style="margin-top:6px;padding:6px 9px;border:1px dashed var(--border);border-radius:7px;font-size:10px;color:var(--dim);line-height:1.5;">\u2696 <b style="color:var(--muted)">Ten-year check (Aug 2026, 247,775 gap days, buys lagged one day):</b> no gap group beat simply holding the market\u2019s quiet shares after costs, and every gap group won LESS often (38\u201343% vs 47%). Faded up-gaps actually did best afterwards and held ones worst \u2014 the market takes back some of what gap-chasers paid. The one steady result: a down-gap that bounced intraday was the weakest group of all (\u22120.44%/5d). A description of the day, not a forecast.</div></div>`;
    const body=sec(`⬆ Gapped up & HELD it <span style="color:var(--green);font-weight:400;font-size:9px;">(buyers stayed)</span>`,held)
      +sec(`⬆ Gapped up, kept part of it`,part)
      +sec(`⬆ Gapped up & FADED <span style="color:var(--orange);font-weight:400;font-size:9px;">(the jump fizzled)</span>`,fade)
      +sec(`⬇ Gapped down but RECOVERED <span style="color:var(--orange);font-weight:400;font-size:9px;">(bounced intraday)</span>`,rec)
      +sec(`⬇ Gapped down, partial bounce`,dpart)
      +sec(`⬇ Gapped down & stayed weak`,weak)
      +`<div style="font-size:9px;color:var(--dim);margin-top:8px;">Tap any line for that share's deep dive. ${noOpen?`Opens missing for ${noOpen} share${noOpen===1?'':'s'} (older stored data) — 🔄 Refresh fills them in. `:''}End-of-day estimates — not advice.</div>`;
    showModal(head+body,'🕳 Gap Report');
  }
}
