  if(typeof scanProgSet==='function')scanProgSet(100);
  if(typeof scanProgHide==='function')scanProgHide();
  if(st){
    if(scored.length){
      st.innerHTML=`🪜 <strong style="color:var(--amber)">${scored.length}</strong> pullbacks in an uptrend — above the key moving averages, dipped toward its short-term average, momentum cooled but not broken`+
        `<br><span style="font-size:9px;color:var(--orange)">The classic “buy the dip” setup. Ranked by how tightly they hug the 20-day MA and how strong the longer trend is. Estimate from end-of-day data — not advice.</span>`;
    }else{
      st.innerHTML='No clean pullbacks right now. <span style="font-size:9px">(needs moving-average &amp; RSI data — try after a full load or another scan; shares need enough price history.)</span>';
    }
  }
