// ── Vertical resize: drag the divider to grow section 3 (and shrink 1&2) ─────
const SETUPROW_H_KEY='asxScreener.setupRowH';
let _vresizing=false;
function startVResize(e){
  _vresizing=true;document.body.classList.add('vresizing');
  const row=document.querySelector('.setup-row');
  const move=ev=>{
    if(!_vresizing)return;
    const top=row.getBoundingClientRect().top;
    let h=ev.clientY-top;
    // keep both areas usable: min 40px for 1&2, leave room for section 3
    const zone=document.querySelector('.load-zone').getBoundingClientRect();
    const maxH=zone.height-160; // reserve space for section 3
    h=Math.max(40,Math.min(maxH>60?maxH:60,h));
    row.style.height=h+'px';
  };
  const up=()=>{
    _vresizing=false;document.body.classList.remove('vresizing');
    try{localStorage.setItem(SETUPROW_H_KEY,parseInt(row.style.height));}catch(_){}
    window.removeEventListener('mousemove',move);window.removeEventListener('mouseup',up);
  };
  window.addEventListener('mousemove',move);window.addEventListener('mouseup',up);
  e.preventDefault();
}
function resetVResize(){
  const row=document.querySelector('.setup-row');
  row.style.height='';
  try{localStorage.removeItem(SETUPROW_H_KEY);}catch(_){}
}

// Make every filter group (.fg) collapsible by clicking its label. Persists
// which groups are collapsed so section 3 can be trimmed to just what you use.
const FG_COLLAPSE_KEY='asxScreener.fgCollapsed.v1';
function loadFgCollapsed(){try{return JSON.parse(localStorage.getItem(FG_COLLAPSE_KEY))||{};}catch(e){return {};}}
function saveFgCollapsed(o){try{localStorage.setItem(FG_COLLAPSE_KEY,JSON.stringify(o));}catch(e){}}
function initCollapsibleGroups(){
  const state=loadFgCollapsed();
  document.querySelectorAll('.panels .fg').forEach((fg,i)=>{
    const lbl=fg.querySelector('.fglbl');
    if(!lbl||lbl.dataset.collapsible)return;
    lbl.dataset.collapsible='1';
    const key='fg'+i;
    // wrap existing label content so the caret + text sit on the left,
    // and the clear button stays on the right.
    const clr=lbl.querySelector('.clr');
    const caret=document.createElement('span');caret.className='fgcaret';caret.textContent='▼';
    // move all non-clear nodes into a left wrapper
    const left=document.createElement('span');left.className='fglbl-left';
    left.appendChild(caret);
    Array.from(lbl.childNodes).forEach(n=>{if(n!==clr&&n!==left)left.appendChild(n);});
    lbl.insertBefore(left,lbl.firstChild);
    // clicking the label (not the clear button) toggles collapse
    lbl.addEventListener('click',e=>{
      if(clr&&clr.contains(e.target))return; // let clear do its thing
      fg.classList.toggle('collapsed');
      const st=loadFgCollapsed();st[key]=fg.classList.contains('collapsed');saveFgCollapsed(st);
    });
    if(state[key])fg.classList.add('collapsed');
  });
}

