// Is a scheduled fetch due right now? (enabled · today is a selected day ·
// current time ≥ scheduled time · not already run today · not already running ·
// and there is SOMETHING to fetch from — a customer key or the Worker.)
function autoDownloadDue(){
  if(!autoDownloadOn())return false;
  if(window._bulkRunning)return false;
  let key=((document.getElementById('apiKey')||{}).value||'').trim();
  if(!key){ try{ key=(localStorage.getItem('asxScreener.apiKey')||'').trim(); }catch(e){} } // v362: box may be empty at startup while the key is saved
  // v488: the SAME test downloadEverything() uses. Since v382 the Worker
  // supplies the data and no customer key is needed, so demanding one here
  // meant the scheduled fetch could never fire for anyone who arrived after
  // v382 — it just returned false, every minute, in silence.
  if(!key && !_serverData())return false;
  const now=new Date();
  const days=autoDownloadDays();
  if(days.length && !days.includes(now.getDay()))return false;
  const [hh,mm]=autoDownloadTime().split(':').map(n=>parseInt(n));
  const schedMins=(hh||0)*60+(mm||0);
  const nowMins=now.getHours()*60+now.getMinutes();
  if(nowMins<schedMins)return false; // not time yet today
  let last=''; try{last=localStorage.getItem(AUTODL_LAST)||'';}catch(e){}
  return last!==now.toISOString().slice(0,10);
}
function markAutoDownloadRun(){ try{localStorage.setItem(AUTODL_LAST,new Date().toISOString().slice(0,10));}catch(e){} }
function runScheduledDownloadIfDue(){
  if(!autoDownloadDue())return;
  if(window._bulkRunning)return;
  const ls=document.getElementById('loadStatus');
  // v488: downloadEverything() asks "you are viewing SAVED shares — re-save the
  // same ones?" in a confirm() box. That is a fair question to put to someone
  // who just pressed a button, and an unanswerable one at the scheduled time
  // with nobody watching — the run would sit on a modal until someone came
  // back. So say what we are waiting for and stay due: the startup fetches
  // today's live prices a few seconds after opening, and the next minute's
  // check then finds a live list and runs properly.
  if(window._offlineMode){
    if(ls)ls.innerHTML='<span style="color:var(--gold)">🔄 Scheduled fetch is waiting for today\'s live prices — it will start on its own once they arrive.</span>';
    return;
  }
  // v488: stamp the day only when a download actually STARTS. It used to be
  // stamped first, so any bail inside downloadEverything() spent the day and
  // the fetch would not try again until tomorrow.
  try{
    markAutoDownloadRun();
    if(ls)ls.innerHTML='<span style="color:var(--gold)">🔄 Scheduled fetch starting…</span>';
    downloadEverything();
  }catch(e){}
}
// While the app is open, check every minute whether the scheduled time has passed.
